/* Who Said It: 182 days of 3 quotes, in order from launch day (15 Nov 2026).
   Each quote: [English, Chinese, speaker, speaker in Chinese, faction, chapter, scene, four options].
   Chinese from the Mao Zonggang edition of the novel; English translations written for this game. */
window.WS_DAYS=[[["Do you still remember the five passes and the generals you killed? A real man values his word.","五關斬將之時，還能記否？大丈夫以信義爲重。將軍深明春秋，豈不知庾公之斯追子濯孺子之事乎？","Cao Cao","曹操","Wei",50,"Pleading for his life on Huarong Road",["Xu You","Chen Gong","Cao Cao","Zhao Yun"]],["Wei Yan always had the look of a rebel. I know he resents me, but I use him because I value his courage. He'll cause trouble in the end.","魏延素有反相，吾知彼常有不平之意，因憐其勇而用之。久後必生患害。","Zhuge Liang","諸葛亮","Shu",100,"Confiding in his officers on the northern campaign",["Liu Bei","Cao Cao","Ma Chao","Zhuge Liang"]],["My sword has just been sharpened. Speak, and if your words don't make sense, you can test the blade.","吾匣中寶劍新磨。汝試言之，其言不通，便請試劍！","Ma Chao","馬超","Shu",65,"Receiving the persuader Li Hui",["Fa Zheng","Ma Chao","Jiang Wan","Liu Bei"]]],[["I'm happy here. I don't miss Shu.","此間樂，不思蜀也。","Liu Shan","劉禪","Shu",119,"Answering Sima Zhao in Luoyang after the fall of Shu",["Zhao Yun","Sun Quan","Sun Ce","Liu Shan"]],["You are a traitor who deceives the emperor. The whole realm wants you dead, not just me!","汝乃欺君罔上之賊，天下皆欲殺汝，豈獨我乎！","Ji Ping","吉平","Han court and others",23,"The court physician caught trying to poison Cao Cao",["Ji Ping","Zuo Ci","Dong Zhuo","Zhou Yu"]],["We are brothers. Make that the theme, but you can't use the word brothers.","吾與汝乃兄弟也。以此爲題。亦不許犯著『兄弟』字樣。","Cao Pi","曹丕","Wei",79,"Giving his younger brother a second impossible test",["Cao Pi","Hua Xin","Zhang Liao","Xu Huang"]]],[["You're afraid of Zhou Yu but not of me? If Zhou Yu can kill you, do you think I can't kill Zhou Yu?","你只怕周瑜，獨不怕我？周瑜殺得你，我豈殺不得周瑜？","Lady Sun","孫夫人","Wu",55,"Scolding the Wu generals who block her escape with Liu Bei",["Sun Ce","Sima Yi","Ma Chao","Lady Sun"]],["Meeting you today is a gift from Heaven. Will you share my pillow tonight and come back to the capital to enjoy riches with me?","今日得見夫人，乃天幸也。今宵願同枕席，隨吾還都安享富貴，何如？","Cao Cao","曹操","Wei",16,"Courting Zhang Ji's widow at Wancheng, a decision that costs him dearly",["Pang De","Dong Zhuo","Xiahou Dun","Cao Cao"]],["Han Xin fought with his back to the river. As they say, put men in a deadly spot and they'll survive.","昔韓信背水爲陣，所謂『致之死地而後生』也。","Xu Huang","徐晃","Wei",71,"Defending his choice to cross the Han River",["Xu You","Cao Mao","Cao Pi","Xu Huang"]]],[["Life and death are fixed by fate. No ritual can change them!","死生有命，不可得而禳也！","Zhuge Liang","諸葛亮","Shu",103,"After his life extending ritual fails",["Zhuge Liang","Zhang Fei","Zhao Yun","Chen Gong"]],["Unless he suffers a bit, how will they believe him?","不受些苦，彼如何肯信？","Zhou Yu","周瑜","Wu",46,"Agreeing to Huang Gai's beating ruse",["Sima Yi","Lady Wu","Zhou Yu","Lady Sun"]],["With Gongjin, my great cause will succeed!","吾得公瑾，大事諧矣！","Sun Ce","孫策","Wu",15,"Reunited with his childhood friend",["Lady Wu","Taishi Ci","Sun Ce","Lu Su"]]],[["Haven't you heard that in war there's no such thing as too much deceit?","豈不聞『兵不厭詐』！","Cao Cao","曹操","Wei",30,"Admitting he lied about his grain supply",["Chen Gong","Cao Cao","Lu Su","Yang Xiu"]],["You've been here a hundred days and spent every one of them drunk. How could the county not be neglected?","汝到任百餘日，終日在醉鄉，安得不廢政事？","Zhang Fei","張飛","Shu",57,"Inspecting Pang Tong's county",["Lu Su","Guan Yu","Liu Shan","Zhang Fei"]],["That wasn't your doing. My own people turned on each other. Why should I submit?","此非汝之能也；乃吾手下之人自相殘害，以致如此。如何肯服！","Meng Huo","孟獲","Rival warlords",88,"After his second capture",["Liu Biao","Liu Qi","Ju Shou","Meng Huo"]]],[["Resist Cao Cao in the north. Make peace with Sun Quan in the east.","北拒曹操，東和孫權。","Zhuge Liang","諸葛亮","Shu",63,"Eight characters left to Guan Yu as he takes charge of Jing Province",["Liu Bei","Zhang Fei","Zhuge Liang","Guan Yu"]],["Meeting a wise lord is like clouds parting to show the blue sky!","今遇明主，如撥雲霧而見青天！","Ma Chao","馬超","Shu",65,"Joining Liu Bei",["Liu Bei","Ma Chao","Zhang Liao","Ma Dai"]],["Our army will be destroyed any day now, and I don't know where my bones will lie!","我軍亡在旦夕，我屍骸不知落何處也！","Ju Shou","沮授","Rival warlords",30,"Imprisoned in Yuan Shao's camp at Guandu",["Ju Shou","Liu Biao","Tian Feng","Meng Huo"]]],[["When I was a baby, if not for Zilong I'd have died in the chaos of battle!","朕昔年幼，非子龍則死於亂軍之中矣！","Liu Shan","劉禪","Shu",97,"Mourning Zhao Yun's death",["Liu Shan","Diao Chan","Chen Gong","Zhuge Liang"]],["Last year I lost my great general Dian Wei on this very spot. How could I not weep?","吾思去年於此地折了吾大將典韋，不由不哭耳！","Cao Cao","曹操","Wei",18,"Passing Wancheng again on campaign",["Zhao Yun","Cao Cao","Zhang Liao","Sima Yi"]],["This is just a trick to confuse people. What use is it?","此乃惑人之術耳，有何益焉！","Lu Xun","陸遜","Wu",84,"Riding into a strange pile of rocks by the river",["Lady Wu","Lü Meng","Huang Gai","Lu Xun"]]],[["I know this horse can run a thousand li a day. If I learn where my brother is, I can reach him in a single day.","吾知此馬日行千里，今幸得之，若知兄長下落，可一日而見面矣。","Guan Yu","關羽","Shu",25,"Explaining why he bowed twice for Red Hare",["Meng Huo","Ma Chao","Guan Yu","Lü Bu"]],["Who taught His Majesty to camp like this? That man should be executed!","是何人教主上如此下寨？可斬此人！","Zhuge Liang","諸葛亮","Shu",84,"Slamming the table after seeing Liu Bei's camp layout at Yiling",["Zhuge Liang","Dong Zhuo","Liu Bei","Zhao Yun"]],["Liu Bei is running wild. He's a real danger at our heart and must be removed quickly.","劉備如此猖狂，真腹心之患也，不可不急除。","Xiahou Dun","夏侯惇","Wei",40,"Reporting the defeat at Bowang to Cao Cao",["Zhang He","Xu Huang","Hua Xin","Xiahou Dun"]]],[["Kongming really is a Sleeping Dragon! I'm no match for him!","孔明真臥龍也！吾不能及！","Lu Xun","陸遜","Wu",84,"Escaping the Stone Sentinel Maze",["Lu Xun","Sun Quan","Chen Gong","Zhuge Liang"]],["This Eight Trigrams formation? Of course I recognise it!","量此『八卦陣』，如何不識！","Sima Yi","司馬懿","Wei",100,"Challenged on the battlefield by Zhuge Liang",["Xu You","Sima Yi","Lu Su","Cao Cao"]],["The sage said that once you offend Heaven, there's no one left to pray to. My mandate is over. What can save me now?","聖人云：獲罪於天，無所禱也。孤天命已盡，安可救乎？","Cao Cao","曹操","Wei",78,"Refusing prayers for his recovery near the end",["Cao Pi","Xiahou Dun","Cao Cao","Hua Xin"]]],[["Where is my son Fengxian?","吾兒奉先何在？","Dong Zhuo","董卓","Han court and others",9,"Crying for help after being wounded at the palace gate",["Huang Zhong","Wang Yun","Lü Bu","Dong Zhuo"]],["I only need a hundred riders to beat them. Why three thousand?","只須百騎，便可破敵，何必三千！","Gan Ning","甘寧","Wu",68,"Volunteering for a night raid on Cao Cao's camp",["Xu You","Gan Ning","Lady Sun","Lady Wu"]],["Killing this sorcerer is no different from slaughtering pigs and dogs!","此等妖人，吾殺之何異屠豬狗！","Sun Ce","孫策","Wu",29,"Determined to execute the Taoist Yu Ji",["Sun Ce","Taishi Ci","Lü Meng","Sun Quan"]]],[["I have a fair bit of money. I'll raise local volunteers and launch a great cause with you. How about it?","吾頗有資財，當招募鄉勇，與公同舉大事，如何？","Zhang Fei","張飛","Shu",1,"Meeting Liu Bei by the recruitment notice",["Guan Yu","Zhao Yun","Zhang Fei","Cao Cao"]],["Under that canopy, in the embroidered robe and golden armour, holding a blade on horseback: that's Yan Liang.","麾蓋之下，繡袍金甲，持刀立馬者，乃顏良也。","Cao Cao","曹操","Wei",25,"Pointing out Yan Liang to Guan Yu from a hilltop",["Xu Chu","Cao Cao","Meng Huo","Deng Ai"]],["A real man would rather die fighting than hide in a wall to stay alive!","大丈夫願臨陣鬥死，豈可入牆而望活乎！","Yuan Shao","袁紹","Rival warlords",7,"Refusing to hide when ambushed at Jieqiao",["Zhang Xiu","Yuan Shao","Ma Teng","Liu Qi"]]],[["First, my brother and I swore to uphold the Han, so I surrender to the Han emperor, not to Cao Cao.","一者，吾與皇叔設誓，共扶漢室，吾今只降漢帝，不降曹操。","Guan Yu","關羽","Shu",25,"Setting his three conditions for laying down arms at Tushan",["Zhang Fei","Guan Yu","Wang Yun","Meng Huo"]],["Lü Bu is no ordinary man. If I had him, what would I fear in the whole realm?","吾觀呂布非常人也。吾若得此人，何慮天下哉！","Dong Zhuo","董卓","Han court and others",3,"Watching Lü Bu fight for Ding Yuan",["Sima Hui","Diao Chan","Ji Ping","Dong Zhuo"]],["Your Highness is mocking me. Every bream in the land has two gills except the Songjiang bream, which has four. That's how you tell.","大王何相欺耶？天下鱸魚只兩腮，惟松江鱸魚有四腮：此可辨也。","Zuo Ci","左慈","Han court and others",68,"Pulling fish from a basin at Cao Cao's banquet",["Zuo Ci","Emperor Xian","Dong Zhuo","Mi Heng"]]],[["I lost my eldest son and my dear nephew without deep grief. I weep only for Dian Wei!","吾折長子、愛姪，俱無深痛，獨號泣典韋也！","Cao Cao","曹操","Wei",16,"After the disaster at Wancheng",["Diao Chan","Zhang Liao","Cao Cao","Sima Yi"]],["The only thing you ever feared was me, and now I've submitted. You lead and I'll serve as your deputy. The realm will be easy to settle.","明公所患，不過於布，布今已服矣。公爲大將，布副之，天下不難定也。","Lü Bu","呂布","Han court and others",19,"Bargaining with Cao Cao for his life",["Yuan Shao","Lü Bu","Ji Ping","Sima Hui"]],["You understand me. Thick clouds, a fierce north wind, snow is coming. My plan can work now.","汝知吾心也。今彤雲密佈，朔風緊急，天將降雪，吾計可施矣。","Zhuge Liang","諸葛亮","Shu",94,"Preparing to trap the Qiang cavalry in the snow",["Zhao Yun","Xu Shu","Zhuge Liang","Jiang Wan"]]],[["Guan Yunchang is here! Pang De, why don't you come and die?","關雲長在此，龐德何不早來受死！","Guan Yu","關羽","Shu",74,"Riding out against Pang De at Fancheng",["Dong Zhuo","Ma Chao","Guan Yu","Liu Bei"]],["A fighting man who doesn't drink? You'll have a cup!","廝殺漢如何不飲酒！我要你吃一盞。","Zhang Fei","張飛","Shu",14,"Forcing Cao Bao to drink at Xuzhou",["Liu Shan","Wei Yan","Zhang Fei","Sima Yi"]],["How does your friendship with Xuande compare with ours?","兄與玄德交，比弟與兄交何如？","Zhang Liao","張遼","Wei",26,"Testing Guan Yu's loyalty in Cao Cao's camp",["Zhang Liao","Jia Xu","Cao Ren","Hua Xin"]]],[["General, you're nearly seventy. How can you say you're not old?","將軍年近七十，如何不老？","Zhuge Liang","諸葛亮","Shu",70,"Goading Huang Zhong before Dingjun Mountain",["Zhuge Liang","Diao Chan","Guan Yu","Huang Zhong"]],["I have killed a loyal and righteous man by mistake!","吾誤殺忠義之士也！","Cao Cao","曹操","Wei",30,"Regretting the execution of Yuan Shao's adviser Ju Shou",["Xiahou Dun","Cao Cao","Zhuge Liang","Xu Huang"]],["Alive I was a servant of the Yuans, dead I'll be a ghost of the Yuans. I'm not a flatterer like you. Kill me now!","吾生爲袁氏臣，死爲袁氏鬼，不似汝輩讒諂阿諛之賊，可速斬我！","Shen Pei","審配","Rival warlords",32,"Refusing to submit after the fall of Ye",["Yuan Shu","Shen Pei","Zhang Ren","Liu Qi"]]],[["Sleeping Dragon and Young Phoenix: win either one and you can bring peace to the realm.","伏龍、鳳雛，兩人得一，可安天下。","Sima Hui","司馬徽","Han court and others",35,"Telling Liu Bei about two hidden talents",["Lü Bu","Yuan Shao","Sima Hui","Diao Chan"]],["Yunchang and I are one body. Our bond still stands. How can I forget it?","雲長與朕猶一體也。大義尚在，豈可忘耶？","Liu Bei","劉備","Shu",81,"Overruling Zhao Yun's objections to the war on Wu",["Liu Bei","Guan Yu","Lü Bu","Ma Chao"]],["Even if there were ambushes on all ten sides, what would I fear?","敵軍如此，雖十面埋伏，吾何懼哉！","Xiahou Dun","夏侯惇","Wei",39,"Ignoring warnings at Bowang",["Cao Mao","Cao Cao","Cheng Yu","Xiahou Dun"]]],[["I see Cao Cao's million men as a swarm of ants. One wave of my hand and they're all dust!","吾視曹操百萬之眾，如群蟻耳！但我一舉手，則皆爲齏粉矣！","Zhuge Liang","諸葛亮","Shu",43,"Explaining to Lu Su why he upset Sun Quan",["Zhao Yun","Zhuge Liang","Chen Gong","Sun Quan"]],["It's hard to fight that lion cub head on!","獅兒難與爭鋒也！","Cao Cao","曹操","Wei",29,"Hearing of Sun Ce's rise in the south",["Xiahou Dun","Xu Chu","Cao Cao","Sima Yi"]],["General, this is no time for weeping. Arrange the funeral, and take charge of the army and the state.","此非將軍哭時也。宜一面治喪事，一面理軍國大事。","Zhang Zhao","張昭","Wu",29,"Pulling the grieving Sun Quan together after his brother's death",["Lu Su","Sun Quan","Huang Gai","Zhang Zhao"]]],[["Pour the wine. I'll be back shortly.","酒且斟下，某去便來。","Guan Yu","關羽","Shu",5,"Before riding out to fight Hua Xiong; he returns with the head while the wine is still warm",["Guan Yu","Lu Su","Zhuge Liang","Xu You"]],["Ziyi, within a few days I'll show you the traitor Cao's head!","子翼，我數日之內，教你看操賊之首！","Zhou Yu","周瑜","Wu",45,"Pretending to talk in his sleep",["Huang Gai","Lady Sun","Zhou Yu","Ma Chao"]],["How dare this boy defy me!","量此小兒，安敢與朕抗耶！","Liu Bei","劉備","Shu",82,"Hearing Wu has sent a young commander against him",["Lady Mi","Guan Yu","Ma Su","Liu Bei"]]],[["I'm sure Cao Cao won't dare come out in this thick fog. Let's just drink and enjoy ourselves, and go back when it lifts.","吾料曹操於重霧中必不敢出。吾等只顧酌酒取樂，待霧散便回。","Zhuge Liang","諸葛亮","Shu",46,"Calming Lu Su as their straw boats drift towards Cao's fleet",["Wang Yun","Zhuge Liang","Zhang Fei","Meng Huo"]],["Mi Heng's writing was famous throughout the land, so I couldn't bring myself to kill him. What talent does this Zhang Song have?","禰衡文章，播於當今，吾故不忍殺之。松有何能？","Cao Cao","曹操","Wei",60,"Refusing to see the envoy from Shu again",["Xiahou Dun","Lu Su","Cao Cao","Deng Ai"]],["If we don't kill Liu Bei now, he'll be the ruin of us later!","今不殺劉備，久後必爲所害！","Chen Gong","陳宮","Han court and others",16,"Warning Lü Bu after the stolen horses",["Chen Gong","Emperor Xian","Dong Zhuo","Wang Yun"]]],[["Zilong is courage through and through!","子龍一身都是膽也！","Liu Bei","劉備","Shu",71,"After Zhao Yun's stand at the Han River",["Lu Su","Zhang Liao","Huang Zhong","Liu Bei"]],["I'm not afraid of dying, so why would I fear the cold? I just worry you're wasting your effort, brother.","死且不怕，豈怕冷乎！但恐哥哥空勞神思。","Zhang Fei","張飛","Shu",37,"Trudging through snow on the second visit",["Zhang Fei","Ma Chao","Ma Dai","Sun Quan"]],["Before we even set out you damaged our morale. Now you've thrown the battle. You deserve to lose your head!","汝未出軍時，已慢吾軍心；今又賣陣，罪當斬首！","Cao Ren","曹仁","Wei",36,"Turning on Li Dian after a defeat by Liu Bei's new strategist",["Cao Ren","Zhang He","Wang Lang","Jia Xu"]]],[["Calm down, Gonglu. If this man talks so big, he must have courage. Let him ride out, and if he loses, punish him then.","公路息怒。此人既出大言，必有勇略。試教出馬，如其不勝，責之未遲。","Cao Cao","曹操","Wei",5,"Backing Guan Yu before the duel with Hua Xiong",["Zhang Liao","Xu You","Pang Tong","Cao Cao"]],["I'm not laughing at anyone else. I'm laughing that Zijing doesn't understand the times.","亮不笑別人，笑子敬不識時務耳。","Zhuge Liang","諸葛亮","Shu",44,"Playing along when Zhou Yu pretends he'll surrender",["Zhuge Liang","Zhang Fei","Ma Dai","Zhao Yun"]],["You're chancellor of the Han and I'm a commoner. Why so humble?","公乃漢相，吾乃布衣，何謙恭如此！","Xu You","許攸","Wei",30,"Greeted by Cao Cao running out barefoot",["Xu You","Cao Cao","Jiang Gan","Yang Xiu"]]],[["They say Brocade Ma Chao lives up to his name!","人言錦馬超，名不虛傳！","Liu Bei","劉備","Shu",65,"Watching Ma Chao from Jiameng Pass",["Liu Bei","Diao Chan","Zhang Fei","Zhang Liao"]],["When a real man takes on a heavy duty, he stops only when he dies.","大丈夫既領重任，除死方休。","Guan Yu","關羽","Shu",63,"Accepting command of Jing Province",["Chen Gong","Pang Tong","Ma Su","Guan Yu"]],["As vanguard I should be first to break the enemy. Why put me somewhere quiet?","某爲前部，理合當先破敵，何故置某於安閒之地？","Wei Yan","魏延","Shu",95,"Complaining about his posting on the first northern campaign",["Wei Yan","Pang Tong","Lady Mi","Zhao Yun"]]],[["These ropes are too tight. Loosen them!","縛太急，乞緩之！","Lü Bu","呂布","Han court and others",19,"Bound at White Gate Tower",["Zhou Yu","Dong Zhuo","Diao Chan","Lü Bu"]],["I have a plan that will keep your whole navy, big ships and small, free from sickness.","某有一策，使大小水軍，并無疾病，安穩成功。","Pang Tong","龐統","Shu",47,"Advising Cao Cao before Red Cliffs",["Zhuge Liang","Lü Bu","Pang Tong","Liu Bei"]],["Following Liu Bei, you're like lonely ghosts following a demon!","汝等隨劉備，如孤魂隨鬼矣！","Xiahou Dun","夏侯惇","Wei",39,"Taunting Zhao Yun before Bowang",["Xun Yu","Pang De","Cheng Yu","Xiahou Dun"]]],[["How could swallows and sparrows understand the ambitions of a swan?","燕雀安知鴻鵠志哉！汝既拿住我，便當解去請賞。何必多問！","Cao Cao","曹操","Wei",4,"Captured at Zhongmou while fleeing the capital",["Zhang Liao","Zhuge Liang","Cao Cao","Zhao Yun"]],["My body is heavy, the horse can't carry me, so it's always thin.","賤軀頗重，馬不能載，因此常瘦。","Guan Yu","關羽","Shu",25,"Explaining his skinny horse to Cao Cao, just before receiving Red Hare",["Sun Quan","Ma Chao","Guan Yu","Zhuge Liang"]],["How could I do that? Governor Liu of Yi Province is also of the imperial clan and has been kind to the people of Shu for years. How could anyone else shake him?","備安敢當此？劉益州亦帝室宗親，恩澤布蜀中久矣。他人豈可得而動搖乎？","Liu Bei","劉備","Shu",60,"Pretending to refuse Zhang Song's offer of Shu",["Wei Yan","Zhang Fei","Liu Bei","Fa Zheng"]]],[["I thought you were a grand old minister of the Han with something wise to say. Who'd have guessed you'd come out with such rubbish!","吾以爲漢朝大老元臣，必有高論，豈期出此鄙言！","Zhuge Liang","諸葛亮","Shu",93,"Answering Wang Lang across the battle lines, before Wang Lang falls dead from his horse",["Zhang Fei","Lü Bu","Zhuge Liang","Yang Xiu"]],["Send an archer out to fight? Hua Xiong will laugh at us!","使一弓手出戰，必被華雄所笑。","Yuan Shao","袁紹","Rival warlords",5,"Before Guan Yu rides out",["Yuan Shu","Zhang Fei","Yuan Shao","Meng Huo"]],["Confucius once asked Laozi about rites. Doesn't that make our families friends for generations?","昔孔子曾問禮於老子，融與君豈非累世通家？","Kong Rong","孔融","Han court and others",11,"As a boy, talking his way in to see Li Ying",["Kong Rong","Diao Chan","Mi Heng","Hua Xiong"]]],[["You're the guest at the table and I'm the prisoner below the steps. Won't you say a single word for me?","公爲坐上客，布爲階下囚，何不發一言而相寬乎？","Lü Bu","呂布","Han court and others",19,"Pleading with Liu Bei at White Gate Tower",["Yuan Shao","Wang Yun","Ma Chao","Lü Bu"]],["I treat people with benevolence, not tricks. Ma Mengqi, rest your troops. I won't chase you.","吾以仁義待人。不施譎詐。馬孟起，你收兵歇息，我不乘勢趕你。","Liu Bei","劉備","Shu",65,"Calling a halt to the night fight with Ma Chao",["Ma Dai","Huang Zhong","Wei Yan","Liu Bei"]],["My fate lies with Heaven. No sorcerer can harm me. Why bother with rituals?","吾命在天，妖人決不能爲禍。何必禳耶？","Sun Ce","孫策","Wu",29,"Refusing prayers after seeing Yu Ji's ghost",["Zhuge Jin","Zhou Tai","Cheng Pu","Sun Ce"]]],[["Killing someone when you know it's wrong is a great injustice!","知而故殺，大不義也。","Chen Gong","陳宮","Han court and others",4,"After Cao Cao kills Lü Boshe on the road",["Chen Gong","Dong Zhuo","Guan Yu","Lü Bu"]],["I didn't listen to Tian Feng, and now I'm beaten. How can I face him when I get back?","吾不聽田豐之言，致有此敗。吾今歸去，羞見此人。","Yuan Shao","袁紹","Rival warlords",31,"Fleeing home after Guandu",["Meng Huo","Ju Shou","Yuan Shao","Ma Chao"]],["In my army grain comes first. Three days late and you should lose your head. You're ten days late! What do you have to say?","吾軍中專以糧爲大事，誤了三日，便該處斬！汝今誤了十日，有何理說？","Zhuge Liang","諸葛亮","Shu",100,"Punishing the officer who delayed the grain transport",["Yan Yan","Zhuge Liang","Ma Dai","Xu Shu"]]],[["Since Heaven made Zhou Yu, why did it also make Zhuge Liang!","既生瑜，何生亮！","Zhou Yu","周瑜","Wu",57,"His dying cry",["Zhou Yu","Pang Tong","Diao Chan","Sun Ce"]],["Zilong followed me through every hardship. His heart is iron and stone. Wealth could never move him.","子龍從我於患難，心如鐵石，非富貴所能動搖也。","Liu Bei","劉備","Shu",41,"Refusing to believe Zhao Yun has defected",["Liu Bei","Sima Yi","Zhuge Liang","Ma Chao"]],["Old Yan Yan can come with me. If anything goes wrong, take this white head of mine first.","老將嚴顏，可同我去。但有疏虞，先納下這白頭。","Huang Zhong","黃忠","Shu",70,"Volunteering to fight Zhang He",["Lady Mi","Guan Yu","Huang Zhong","Ma Chao"]]],[["Stop lying! Your grain is gone!","休瞞我！糧已盡矣！","Xu You","許攸","Wei",30,"Finally calling out Cao Cao at Guandu",["Zhang Liao","Xu You","Zhang Fei","Sima Yi"]],["I already serve a nobleman, and now you'd hand me to a household slave? I'd rather die than be shamed!","妾身已事貴人，今忽欲下賜家奴，妾寧死不辱！","Diao Chan","貂蟬","Han court and others",9,"When Dong Zhuo offers to give her away",["Zuo Ci","Zhuge Liang","Diao Chan","Chen Gong"]],["I'm not honouring your rank. I'm honouring you as a descendant of the imperial house.","吾非敬汝名爵，吾敬汝是帝室之冑耳。","Yuan Shao","袁紹","Rival warlords",5,"Inviting Liu Bei to sit with the coalition lords",["Zhang Song","Shen Pei","Yuan Shao","Yuan Shu"]]],[["Your Excellency has the might of Heaven. We southerners will never rebel again!","丞相天威，南人不復反矣！","Meng Huo","孟獲","Rival warlords",90,"Submitting after his seventh capture",["Huang Zhong","Cao Cao","Meng Huo","Yuan Shao"]],["Shiyuan isn't a man for running a small county. His learning is ten times mine.","士元非百里之才，胸中之學，勝亮十倍。亮曾有薦書在士元處，曾達主公否？","Zhuge Liang","諸葛亮","Shu",57,"Asking Liu Bei why Pang Tong is stuck as a magistrate",["Pang Tong","Zhuge Liang","Dong Zhuo","Xu Shu"]],["If I can't beat you, I swear I won't go back to camp!","我勝你不得，誓不回寨！","Ma Chao","馬超","Shu",65,"Duelling Zhang Fei into the night",["Lady Mi","Liu Chen","Jiang Wan","Ma Chao"]]],[["Yuan Shu is a dry bone in a tomb. Sooner or later I'll catch him.","塚中枯骨，吾早晚必擒之。","Cao Cao","曹操","Wei",21,"Rejecting Liu Bei's first suggestion of a hero",["Lü Bu","Yang Xiu","Pang Tong","Cao Cao"]],["My beard is rather long, so the Chancellor gave me a bag for it.","臣髯頗長，丞相賜囊貯之。","Guan Yu","關羽","Shu",25,"Explaining his beard bag to the emperor",["Zhang Fei","Guan Yu","Zhao Yun","Huang Zhong"]],["Liu Bei is a hero. If you don't deal with him early, he'll be trouble later.","劉備，英雄也。今不早圖，後必爲患。","Xun Yu","荀彧","Wei",16,"Advising Cao Cao after Liu Bei comes to him for help",["Xun Yu","Xu Chu","Xu You","Cheng Yu"]]],[["With Fengxian beside me, I can sleep on a high pillow without a care!","吾有奉先，高枕無憂矣！","Dong Zhuo","董卓","Han court and others",5,"As the coalition gathers against him",["Lü Bu","Wang Yun","Dong Zhuo","Zhuge Liang"]],["The traitor to the Han is a public enemy. Avenging a brother is private. Please put the realm first.","漢賊之仇，公也；兄弟之仇，私也。願以天下爲重。","Zhao Yun","趙雲","Shu",81,"Urging Liu Bei to attack Wei, not Wu",["Huang Zhong","Liu Shan","Zhao Yun","Diao Chan"]],["There are no heroes in the realm today except you, General. I'm not honouring your rank, I'm honouring your talent.","方今天下別無英雄，惟有將軍耳。允非敬將軍之職，敬將軍之才也。","Wang Yun","王允","Han court and others",8,"Flattering Lü Bu at a private banquet",["Hua Tuo","Xu Shao","Kong Rong","Wang Yun"]]],[["I am chancellor of the Han, so the Han is me. Agreed.","吾爲漢相，漢即吾也。此可從之。","Cao Cao","曹操","Wei",25,"Hearing Guan Yu will surrender to the Han but not to him",["Meng Huo","Xu You","Cao Cao","Chen Gong"]],["Liu Bei took Liu Zhang's land by trickery and the people of Shu haven't accepted him. Now you have Hanzhong, Yi Province is shaking. Advance now and it will collapse.","劉備以詐力取劉璋，蜀人尚未歸心。今主公已得漢中，益州震動。可速進兵攻之，勢必瓦解。智者貴於乘時，時不可失也。","Sima Yi","司馬懿","Wei",67,"Urging Cao Cao to march on Shu",["Lu Su","Sima Yi","Zhang He","Cao Ren"]],["The officials and generals of Wu are all your old servants. I'm young and untalented. How can I command them?","江東文武，皆大王故舊之臣；臣年幼無才，安能制之？","Lu Xun","陸遜","Wu",83,"Hesitating when Sun Quan offers him the top command",["Cheng Pu","Lu Xun","Zhou Yu","Kan Ze"]]],[["Cao Cao and Sun Quan are like lines on my palm to me. Why worry about a tiny county?","所廢之事何在？曹操、孫權，吾視之若掌上觀文，量此小縣，何足介意？","Pang Tong","龐統","Shu",57,"Answering Zhang Fei's complaint that he neglects his duties",["Pang Tong","Wang Yun","Liu Bei","Huang Zhong"]],["I've asked Heaven for a sign too. If I'm to destroy the traitor Cao, let this stone split as well.","吾亦問天買卦。若破得曹賊，亦斷此石。","Liu Bei","劉備","Shu",54,"Slashing a rock at Ganlu Temple next to Sun Quan",["Zhao Yun","Zhang Liao","Liu Bei","Ma Chao"]],["We'll die with nowhere to be buried!","吾等死無葬身之地矣！","Chen Gong","陳宮","Han court and others",19,"After Lü Bu refuses yet another plan",["Chen Gong","Kong Rong","Xu Shao","Lü Bu"]]],[["Zhou Yu's death is near! A child could see through a plan like this!","周瑜死日近矣！這等計策，小兒也瞞不過！","Zhuge Liang","諸葛亮","Shu",56,"Seeing through Wu's offer to borrow a road through Jing Province",["Yuan Shao","Zhuge Liang","Guan Yu","Huang Zhong"]],["At home we are father and son. On duty we are lord and subject. The law makes no allowance for feelings.","居家爲父子，受事爲君臣。法不徇情，爾宜深戒。","Cao Cao","曹操","Wei",72,"Sending his son Cao Zhang to war",["Yang Xiu","Guo Jia","Cao Pi","Cao Cao"]],["Huang Zhong has brains, not just courage.","黃忠有謀，非止勇也。","Zhang He","張郃","Wei",70,"Warning his colleagues before Dingjun Mountain",["Cao Mao","Deng Ai","Zhang He","Cheng Yu"]]],[["You've invaded our land with no just cause! Here there are generals who lose their heads, but none who surrender!","汝等無義，侵我州郡！但有斷頭將軍！無降將軍！","Yan Yan","嚴顏","Shu",63,"Defying Zhang Fei after being captured",["Liu Bei","Zhao Yun","Yan Yan","Diao Chan"]],["Red Hare crosses water as if it were flat ground. What's there to fear?","吾有赤兔馬，渡水如平地，又何懼哉！","Lü Bu","呂布","Han court and others",19,"Shrugging off the flooding of Xiapi",["Mi Heng","Yuan Shao","Lü Bu","Hua Tuo"]],["Yuanzhi, do you really mean to ruin my plan?","元直真欲破我計耶？","Pang Tong","龐統","Shu",48,"Caught by an old friend as he leaves Cao's camp",["Ma Chao","Jiang Wei","Pang Tong","Liu Bei"]]],[["Tao Qian let his men kill my father. I cannot live under the same sky as him! I will wash Xuzhou clean of them.","陶謙縱兵殺吾父，此仇不共戴天！吾今悉起大軍，洗蕩徐州，方雪吾恨！","Cao Cao","曹操","Wei",10,"On hearing of his father's murder",["Cao Cao","Zhang Liao","Sima Yi","Yuan Shao"]],["I'm not laughing at you. I'm laughing that Huang Gongfu misjudged people.","吾不笑你。吾笑黃公覆不識人耳。","Kan Ze","闞澤","Wu",47,"Laughing in Cao Cao's face while being dragged off to execution",["Xu You","Kan Ze","Zhang Zhao","Sun Quan"]],["The emperor's star is dim, traitors ruin the state, the people are crushed and the capital is empty!","帝星不明，賊臣亂國，萬民塗炭，京城一空！","Sun Jian","孫堅","Wu",6,"Weeping over the ruins of Luoyang",["Lu Su","Cheng Pu","Sun Jian","Taishi Ci"]]],[["Yuan Shao has ten weaknesses and you have ten strengths. His army may be large, but it's nothing to fear.","今紹有十敗，公有十勝，紹兵雖盛，不足懼也。","Guo Jia","郭嘉","Wei",18,"Encouraging Cao Cao before the war with Yuan Shao",["Zhuge Liang","Guo Jia","Yang Xiu","Liu Bei"]],["A loyal subject would rather die than be disgraced. How can a real man serve two lords?","嫂嫂休要被他瞞過了。忠臣寧死而不辱，大丈夫豈有事二主之理！","Zhang Fei","張飛","Shu",28,"Refusing to believe Guan Yu at Gucheng",["Xu Shu","Zhang Fei","Lü Bu","Liu Bei"]],["Boyue, this has nothing to do with you. Just send out Yang Yi!","伯約，不干你事。只教楊儀來！","Wei Yan","魏延","Shu",105,"At the gates of Nanzheng after rebelling",["Wei Yan","Ma Su","Liu Chen","Liu Bei"]]],[["I made this law myself and I broke it myself. How can I make the army obey?","吾自製法，吾自犯之，何以服眾？","Cao Cao","曹操","Wei",17,"After his horse tramples the wheat he ordered everyone to protect",["Xu You","Sun Ce","Cao Cao","Yuan Shao"]],["How could ordinary birds understand the ambitions of the roc that flies ten thousand li?","鵬飛萬里，其志豈群鳥能識哉？","Zhuge Liang","諸葛亮","Shu",43,"Answering Zhang Zhao in the great debate with Wu's scholars",["Xu Shu","Wang Yun","Ma Chao","Zhuge Liang"]],["This is Heaven's gift, and the spirit of my third brother too!","此天之所賜，亦由三弟之靈也！","Liu Bei","劉備","Shu",83,"When Zhang Fei's murderers are handed over to him",["Liu Bei","Huang Zhong","Ma Dai","Liu Shan"]]],[["What a pity my top generals Yan Liang and Wen Chou aren't here! With either one, why fear Hua Xiong?","可惜吾上將顏良、文醜未至！得一人在此，何懼華雄！","Yuan Shao","袁紹","Rival warlords",5,"As Hua Xiong cuts down the coalition's champions",["Yuan Shao","Meng Huo","Huang Zhong","Zhang Fei"]],["One roar from me and they fell back miles. How would they dare chase us?","他被我一喝，倒退數里，何敢再追？","Zhang Fei","張飛","Shu",42,"Pleased with himself after Changban Bridge",["Zhang Fei","Zhao Yun","Sun Quan","Liu Shan"]],["The fiercest fighter I've ever seen is Xu Chu. A real tiger fool!","吾見惡戰者莫如許褚，真虎癡也！","Ma Chao","馬超","Shu",59,"Telling Han Sui about his duel with the bare chested Xu Chu",["Jiang Wan","Wei Yan","Zhang Fei","Ma Chao"]]],[["Sandal selling brat, always sending your adopted son out to fight! Wait till I call my yellow bearded boy, he'll make mincemeat of your fake son!","賣履小兒，常使假子拒敵！吾若喚黃須兒來，汝假子爲肉泥矣！","Cao Cao","曹操","Wei",72,"Taunting Liu Bei at Hanzhong",["Yang Xiu","Zhao Yun","Zhang Liao","Cao Cao"]],["When a bird is about to die, its cry is sad. When a man is about to die, his words are good.","聖人云：『鳥之將死，其鳴也哀；人之將死，其言也善。』","Liu Bei","劉備","Shu",85,"Opening his final words to Zhuge Liang",["Xu Shu","Liu Bei","Lü Bu","Liu Shan"]],["These are the heroes of Jiangdong. Today's gathering should be called the Gathering of Heroes.","此皆江東之英傑。今日此會，可名『群英會』。","Zhou Yu","周瑜","Wu",45,"Toasting the generals at the banquet for Jiang Gan",["Zhou Yu","Sun Jian","Sun Quan","Gan Ning"]]],[["Losing those two from Jiangdong would be like one leaf off a great tree, one grain from the granary.","江東去此兩人，如大木飄一葉，太倉減一粟耳。而操得之，必大喜而去。","Zhuge Liang","諸葛亮","Shu",44,"Suggesting Wu just hand the Qiao sisters to Cao Cao",["Zhao Yun","Zhuge Liang","Ma Chao","Dong Zhuo"]],["I refused to accept I was old, and now I'll die here!","吾不服老，死於此地矣！","Zhao Yun","趙雲","Shu",92,"Surrounded at Fengming Mountain",["Zhang Fei","Guan Yu","Zhuge Liang","Zhao Yun"]],["Don't be alarmed, Chancellor. One Zhang Fei is nothing to be afraid of! Turn back now and we can catch Liu Bei.","丞相休驚。料張飛一人，何足深懼！今急回軍殺去，劉備可擒也。","Zhang Liao","張遼","Wei",42,"After the panic at Changban Bridge",["Xu Chu","Cao Pi","Cheng Yu","Zhang Liao"]]],[["I've sent you beauties, gold and silk and you never bowed. Now I give you a horse and you bow twice. Why value a beast above people?","吾累送美女金帛，公未嘗下拜；今吾贈馬，乃喜而再拜：何賤人而貴畜耶？","Cao Cao","曹操","Wei",25,"After Guan Yu thanks him for Red Hare",["Yang Xiu","Sima Yi","Yuan Shao","Cao Cao"]],["Without entering the tiger's den, how do you catch the tiger cub?","不入虎穴，焉得虎子？","Huang Zhong","黃忠","Shu",70,"Pushing ahead at Dingjun Mountain",["Ma Chao","Xu You","Huang Zhong","Xu Shu"]],["The late emperor didn't found this state easily. Now you'd throw it away in a day. I'd rather die than be shamed!","先帝非容易創立基業，今一旦棄之，吾寧死不辱也！","Liu Chen","劉諶","Shu",118,"The Prince of Beidi, protesting his father's surrender",["Ma Dai","Liu Chen","Zhang Fei","Zhuge Liang"]]],[["You really are a god, sir! How did you know there'd be such a thick fog today?","先生真神人也！何以知今日如此大霧？","Lu Su","魯肅","Wu",46,"After the straw boats return full of arrows",["Zhuge Liang","Sun Quan","Lu Su","Sun Ce"]],["Zhang Junyi's death is my fault!","張雋乂身死，吾之過也！","Sima Yi","司馬懿","Wei",101,"After Zhang He is killed in an ambush at Mumen",["Sima Yi","Pang De","Zhou Yu","Cao Pi"]],["Brother, do you know the story of Bo Yi and Shu Qi?","弟知伯夷、叔齊乎？","Zhuge Jin","諸葛瑾","Wu",44,"Trying to persuade his younger brother to serve Wu",["Lü Meng","Zhuge Jin","Sun Ce","Lady Wu"]]],[["You'll be an able minister in times of order and a treacherous hero in times of chaos.","子治世之能臣，亂世之奸雄也。","Xu Shao","許劭","Han court and others",1,"His verdict on the young Cao Cao",["Pang Tong","Chen Gong","Xu Shao","Zhou Yu"]],["This is the moment Heaven destroys him. One battle and the realm is settled. Why do you all hold back?","董賊焚燒宮室，劫遷天子，海內震動，不知所歸。此天亡之時也，一戰而天下定矣。諸公何疑而不進？","Cao Cao","曹操","Wei",6,"Urging the coalition lords to chase Dong Zhuo from Luoyang",["Sima Yi","Zhuge Liang","Guo Jia","Cao Cao"]],["I watched the stars last night and saw one fall in the northwest. A member of the imperial clan must have died.","亮夜觀星象，見西北有星墜地，必應折一皇族。","Zhuge Liang","諸葛亮","Shu",53,"Predicting the death of Liu Qi",["Liu Shan","Zhuge Liang","Xu Shu","Wei Yan"]]],[["By imperial decree, I punish this traitor!","有詔討賊！","Lü Bu","呂布","Han court and others",9,"Driving his halberd into Dong Zhuo at the palace gate",["Lü Bu","Dong Zhuo","Yang Xiu","Pang Tong"]],["Kongming has tricks that appear and vanish like spirits. I can't match him!","孔明真有神出鬼沒之計，吾不能及也！","Sima Yi","司馬懿","Wei",99,"After another ambush in the Qishan campaigns",["Yang Xiu","Sun Quan","Sima Yi","Jia Xu"]],["That would be like throwing a bright pearl into the dark. Go to Jing Province and serve Imperial Uncle Liu. He'll surely make great use of you.","此明珠暗投矣，可往荊州投劉皇叔，必然重用。","Lu Su","魯肅","Wu",57,"Advising Pang Tong after Sun Quan rejects him",["Lu Xun","Huang Gai","Lu Su","Lady Wu"]]],[["Ma Chao is no less brave than Lü Bu!","馬超不減呂布之勇！","Cao Cao","曹操","Wei",59,"Watching Ma Chao fight at Tong Pass",["Cao Cao","Zhang Fei","Sima Yi","Yang Xiu"]],["Heaven and earth are so wide, yet there isn't a single man in them!","天地雖闊，何無一人也！","Mi Heng","禰衡","Han court and others",23,"Insulting Cao Cao's whole court",["Wang Yun","Dong Zhuo","Mi Heng","Pang Tong"]],["You've just arrived and instead of teaching me the right way, you teach me to benefit myself at others' cost? I won't hear it!","公初至此，不教吾以正道，便教作利己妨人之事，備不敢聞教！","Liu Bei","劉備","Shu",35,"Rejecting advice to give away a horse that brings bad luck",["Liu Bei","Zhuge Liang","Liu Shan","Ma Dai"]]],[["Releasing Xiahou Mao is like releasing a duck. Getting Boyue is getting a phoenix.","吾放夏侯楙，如放一鴨耳。今得伯約，得一鳳也。","Zhuge Liang","諸葛亮","Shu",93,"Delighted after winning over Jiang Wei",["Zhuge Liang","Liu Bei","Zhang Fei","Zhang Liao"]],["I can predict what he'll do alive, but not what he'll do dead!","吾能料其生，不能料其死也！","Sima Yi","司馬懿","Wei",104,"Hearing the \"living\" Zhuge Liang was only a statue",["Ma Chao","Sima Yi","Xu You","Xun Yu"]],["When two states are at war, envoys are not executed.","兩國相爭，不斬來使。","Lu Su","魯肅","Wu",45,"Stopping Zhou Yu from killing Liu Bei's messenger",["Lu Su","Zhang Zhao","Lady Wu","Lu Xun"]]],[["I only want to borrow your head to show the troops.","欲借汝頭以示眾耳。","Cao Cao","曹操","Wei",17,"To the granary officer Wang Hou when grain runs short",["Zhang Liao","Zhuge Liang","Yang Xiu","Cao Cao"]],["You call yourself chancellor of the Han, but you're a traitor to the state. I am of the imperial clan, sent by the emperor's secret decree to punish you!","汝託名漢相，實爲國賊。吾乃漢室宗親，奉天子密詔，來討反賊！","Liu Bei","劉備","Shu",31,"Facing Cao Cao on the battlefield at Runan",["Pang Tong","Ma Dai","Liu Bei","Sun Ce"]],["Instead of getting me the governorship of Xuzhou, you got titles for yourselves. I've been sold out by you and your father!","汝不爲吾求徐州牧，而乃自求爵祿。汝父教我協同曹公，絕婚公路，今吾所求，終無一獲，而汝父子俱各顯貴。吾爲汝父子所賣耳！","Lü Bu","呂布","Han court and others",16,"Raging at Chen Deng",["Xu Shao","Ji Ping","Lü Bu","Emperor Xian"]]],[["In leading the men of Jiangdong into battle against the realm, you're not my equal. In choosing the able and keeping Jiangdong safe, I'm not yours.","若舉江東之眾，決機於兩陣之間，與天下爭衡，卿不如我；舉賢任能，使各盡力以保江東，我不如卿。","Sun Ce","孫策","Wu",29,"Handing his seal to his brother on his deathbed",["Huang Zhong","Sun Ce","Zhou Yu","Sun Quan"]],["This is a matter of state. There's no need to discuss it at a banquet.","此國家之事，筵間不必論之。","Guan Yu","關羽","Shu",66,"Brushing off Lu Su's demand for Jing Province at the Single Sword Meeting",["Yuan Shao","Liu Shan","Wei Yan","Guan Yu"]],["If not for the faces of all these officers, your head would come off! I'll spare your life for now.","若不看眾官面皮，決須斬首！今且免死！","Zhou Yu","周瑜","Wu",46,"Ordering Huang Gai beaten in front of the camp",["Zhou Yu","Zhuge Jin","Sun Quan","Cheng Pu"]]],[["I've watched the heavens. The traitor Cao isn't fated to die yet. Leaving him this favour for Yunchang to repay isn't a bad thing.","亮夜觀乾象，操賊未合身亡。留這人情，教雲長做了，亦是美事。","Zhuge Liang","諸葛亮","Shu",49,"Explaining why he sent Guan Yu to Huarong Road",["Pang Tong","Zhou Yu","Lü Bu","Zhuge Liang"]],["If you die like this, what becomes of your old mother, your wife and children?","公如是，奈公之老母妻子何？","Cao Cao","曹操","Wei",19,"Questioning a captured strategist before his execution",["Zhou Yu","Cao Cao","Cao Pi","Zhang Liao"]],["Chase them again now and you'll win a great victory. If not, cut off my head.","今番追去，必獲大勝。如其不然，請斬吾首。","Jia Xu","賈詡","Wei",18,"Telling Zhang Xiu to pursue after the first pursuit failed",["Wang Lang","Xiahou Dun","Cao Pi","Jia Xu"]]],[["Brat, mocking my age! My blade isn't old!","豎子欺吾年老！吾手中寶刀卻不老！","Huang Zhong","黃忠","Shu",70,"Charging at Han Hao and Xiahou Shang",["Sun Ce","Sima Yi","Pang Tong","Huang Zhong"]],["Southerners sail boats, northerners ride horses. It's true then.","南人駕船，北人乘馬，信有之也。","Liu Bei","劉備","Shu",54,"Watching boats on the river while staying in Wu",["Wang Yun","Wei Yan","Guan Yu","Liu Bei"]],["That traitor Cao insults me too far!","操賊辱我太甚！","Zhang Xiu","張繡","Rival warlords",16,"Learning Cao Cao has taken his widowed aunt",["Ma Teng","Tian Feng","Zhang Xiu","Zhang Ren"]]],[["Gongjin's illness? I can cure that too.","公瑾之病，亮亦能醫。","Zhuge Liang","諸葛亮","Shu",49,"Hearing Zhou Yu has collapsed before the battle",["Pang Tong","Sun Quan","Zhang Fei","Zhuge Liang"]],["Kongming really is dead! After them, quickly!","孔明真死矣！可速追之！","Sima Yi","司馬懿","Wei",104,"Seeing the Shu army retreat",["Chen Gong","Xu You","Cao Cao","Sima Yi"]],["For forty years I've travelled the realm. From the emperor down to the commoners, nobody doesn't fear me. What demon dares defy me?","吾平生遊歷普天之下四十餘年，上至天子，下及庶人，無不懼孤；是何妖神，敢違孤意！","Cao Cao","曹操","Wei",78,"Ordering a sacred pear tree cut down for his new palace",["Cao Cao","Deng Ai","Guo Jia","Cao Pi"]]],[["All under heaven is in my hands! If I do this, who dares disobey? Do you think my sword isn't sharp?","天下事在我！我今爲之，誰敢不從？汝視我之劍不利否？","Dong Zhuo","董卓","Han court and others",3,"Threatening Yuan Shao at court",["Dong Zhuo","Huang Zhong","Wang Yun","Zhao Yun"]],["Because they block my view of Xu Yuanzhi.","因阻吾望徐元直之目也。","Liu Bei","劉備","Shu",36,"Explaining why he wants the trees cut down",["Guan Yu","Wei Yan","Zhuge Liang","Liu Bei"]],["If the young master isn't here, then the cities must be handed back to Wu!","若公子不在，須將城池還我東吳。","Lu Su","魯肅","Wu",52,"Demanding Jing Province back after Liu Qi dies",["Lu Su","Cheng Pu","Zhuge Jin","Taishi Ci"]]],[["I am Zhang Yide of Yan! Who dares fight me to the death?","我乃燕人張翼德也！誰敢與我決一死戰？","Zhang Fei","張飛","Shu",42,"Standing alone on Changban Bridge against Cao's army",["Zhuge Liang","Yang Xiu","Guan Yu","Zhang Fei"]],["Catching this man is as easy as taking something from a bag. What matters is winning his heart, then the south will settle.","吾擒此人，如囊中取物耳。直須降伏其心，自然平矣。","Zhuge Liang","諸葛亮","Shu",88,"Explaining why he keeps releasing Meng Huo",["Liu Bei","Zhuge Liang","Wei Yan","Lu Su"]],["Lu Xun is just a scholar, no match for Liu Bei. I fear he won't do.","陸遜乃一書生耳，非劉備敵手；恐不可用。","Zhang Zhao","張昭","Wu",83,"Objecting to a young commander before Yiling",["Zhang Zhao","Zhou Tai","Cheng Pu","Sun Quan"]]],[["I've received great kindness from the King of Wei and swear to repay it with my life. Either I kill Guan Yu or he kills me, and if he doesn't, I'll kill myself. That's why I brought this coffin.","吾受魏王厚恩，誓以死報。今去樊城與關某決戰，我若不能殺彼，必爲彼所殺；即不爲彼所殺，我亦當自殺。故先備此櫬，以示無空回之理。","Pang De","龐德","Wei",74,"Setting out for Fancheng with a coffin in tow",["Guan Yu","Sima Yi","Pang De","Zhang Liao"]],["A real man born between heaven and earth, how can I stay stuck under someone else forever?","大丈夫生居天地間，豈能鬱鬱久居人下？","Lü Bu","呂布","Han court and others",9,"Venting his rage at Dong Zhuo to Wang Yun",["Lü Bu","Chen Gong","Sima Hui","Diao Chan"]],["Your virtue is so towering that even Yi Yin and the Duke of Zhou couldn't match it.","太師盛德巍巍，伊、周不能及也。","Wang Yun","王允","Han court and others",8,"Flattering Dong Zhuo at a banquet in his home",["Mi Heng","Dong Zhuo","Wang Yun","Diao Chan"]]],[["I wasn't going to beat you, but you used Lü Bu to scare me, so now I will. Beating you is beating Lü Bu!","我本不欲打你，你把呂布來嚇我，我偏要打你。我打你便是打呂布。","Zhang Fei","張飛","Shu",14,"Thrashing Cao Bao, which costs Liu Bei Xuzhou",["Zhang Fei","Huang Zhong","Xu You","Chen Gong"]],["I've captured you now. Are you convinced?","吾今擒汝，汝心服否？","Zhuge Liang","諸葛亮","Shu",87,"After the first capture of Meng Huo",["Zhuge Liang","Zhao Yun","Pang Tong","Guan Yu"]],["I want Kongming dead, but I'd be laughed at, so I'll borrow Cao Cao's hand to kill him.","吾欲殺孔明，恐惹人笑，故借曹操之手殺之，以絕後患耳。","Zhou Yu","周瑜","Wu",45,"Sending Zhuge Liang to raid Cao's grain",["Zhang Zhao","Zhou Yu","Lady Wu","Cheng Pu"]]],[["Those who obey me live. Those who defy me die!","順我者生，逆我者死！","Dong Zhuo","董卓","Han court and others",3,"Silencing objections to deposing the emperor",["Zhuge Liang","Chen Gong","Sun Quan","Dong Zhuo"]],["The Chancellor wasn't the one dreaming. You are!","丞相非在夢中，君乃在夢中耳！","Yang Xiu","楊修","Wei",72,"At the funeral of an attendant Cao Cao \"killed in his sleep\"",["Sima Yi","Yang Xiu","Xiahou Dun","Pang De"]],["We in Shu have never seen weapons like these. We govern by benevolence.","吾蜀中不曾見此兵革，但以仁義治人。","Zhang Song","張松","Rival warlords",60,"Unimpressed by Cao Cao's military parade",["Zhang Song","Shen Pei","Ma Teng","Zhang Ren"]]],[["If you're really sincere, then before I finish three rolls of the drum, cut down that general!","你果有真心，我這裏三通鼓罷。便要你斬來將！","Zhang Fei","張飛","Shu",28,"Testing Guan Yu as Cai Yang approaches",["Zhou Yu","Zhang Fei","Zhang Liao","Pang Tong"]],["How could I not know five armies are coming? I'm not watching the fish, I'm thinking.","五路兵至，臣安得不知，臣非觀魚，有所思也。","Zhuge Liang","諸葛亮","Shu",85,"Found by the young emperor feeding fish during a crisis",["Liu Shan","Zhuge Liang","Ma Chao","Ma Dai"]],["Huang Gongfu and I come to surrender with all our hearts, like babies longing for their parents. How could there be any deceit?","吾與黃公覆傾心投降，如嬰兒之望父母，豈有詐乎？","Kan Ze","闞澤","Wu",47,"Delivering a false surrender letter",["Sun Quan","Zhou Tai","Kan Ze","Lü Meng"]]],[["My title is Young Phoenix and this place is called Fallen Phoenix Slope. This bodes ill for me!","吾道號鳳雛，此處名落鳳坡，不利於吾！","Pang Tong","龐統","Shu",63,"Moments before an ambush near Luo",["Diao Chan","Chen Gong","Liu Bei","Pang Tong"]],["The only two I was worried about are gone. Now I have no worries.","吾所患者，此二人耳。今既剿除，吾無憂矣。","Zhou Yu","周瑜","Wu",45,"After Cao Cao executes his own admirals",["Lü Meng","Xu You","Sun Ce","Zhou Yu"]],["Wu murdered my brother, and today you dare come here with clever words?","汝東吳害了朕弟，今日敢以巧言來說乎？","Liu Bei","劉備","Shu",82,"To Zhuge Jin, sent to make peace",["Liu Bei","Liu Chen","Yan Yan","Huang Zhong"]]],[["Why use an ox cleaver to kill a chicken? No need for you to go, Marquis Wen. I'll take the lords' heads as easily as reaching into a bag.","『割雞焉用牛刀』？不勞溫侯親往。吾斬眾諸侯首級，如探囊取物耳！","Hua Xiong","華雄","Han court and others",5,"Volunteering to face the coalition in Lü Bu's place",["Yang Xiu","Diao Chan","Hua Xiong","Zhao Yun"]],["Cao Cao is a traitor to the Han. Why even ask?","曹操乃漢賊也，又何必問？","Zhuge Liang","諸葛亮","Shu",43,"Answering a Wu scholar who asks about Cao Cao",["Zhao Yun","Zhuge Liang","Ma Su","Meng Huo"]],["I always thought Zhou Lang was weak and unfit to lead. Now he shows he's a real general. How could I not submit?","吾素欺周郎懦弱不足爲將，今能如此，真將才也！我如何不服？","Cheng Pu","程普","Wu",44,"After Zhou Yu takes firm command before Red Cliffs",["Sun Ce","Zhuge Jin","Lady Sun","Cheng Pu"]]],[["So Cai Mao and Zhang Yun are in league with Wu!","原來蔡瑁、張允結連東吳！","Jiang Gan","蔣幹","Wei",45,"Finding a forged letter on Zhou Yu's desk",["Sima Yi","Ma Chao","Guan Yu","Jiang Gan"]],["A little county of a hundred li, a few small cases. How hard can that be? Sit down, General, while I deal with them.","量百里小縣，些小公事，何難決斷？將軍少坐，待我發落。","Pang Tong","龐統","Shu",57,"Clearing a hundred days of backlog in half a day",["Zhao Yun","Pang Tong","Yang Xiu","Xu Shu"]],["Last night I dreamed a dragon wrapped itself round me, and today comes this happy news. This chance must not be lost!","吾夜夢一龍罩身，今日果得此喜信。時哉不可失！","Dong Zhuo","董卓","Han court and others",9,"Lured back to the capital with promises of the throne",["Emperor Xian","Lü Bu","Dong Zhuo","Chen Gong"]]],[["I truly didn't know! A slip of the tongue. I deserve death! I deserve death!","亮實不知。失口亂言，死罪！死罪！","Zhuge Liang","諸葛亮","Shu",44,"After learning one of the Qiao sisters is Zhou Yu's wife",["Liu Bei","Yang Xiu","Zhao Yun","Zhuge Liang"]],["The Sleeping Dragon has found his lord but not his time. What a pity!","臥龍雖得其主，不得其時，惜哉！","Sima Hui","司馬徽","Han court and others",37,"Walking away from Liu Bei's camp with a sigh",["Dong Zhuo","Ji Ping","Wang Yun","Sima Hui"]],["In Shu we have no flatterers.","吾川中無謅佞之人也。","Zhang Song","張松","Rival warlords",60,"Answering the arrogant officials in Cao Cao's capital",["Liu Biao","Meng Huo","Zhang Ren","Zhang Song"]]],[["I am a descendant of Prince Jing of Zhongshan, great great grandson of Emperor Jing, grandson of Liu Xiong, son of Liu Hong.","臣乃中山靖王之後，孝景皇帝閣下玄孫，劉雄之孫，劉弘之子也。","Liu Bei","劉備","Shu",20,"Introducing his family tree to the young emperor",["Sun Ce","Yuan Shao","Liu Bei","Guan Yu"]],["General Xu truly has the style of Zhou Yafu!","徐將軍真有周亞夫之風矣！","Cao Cao","曹操","Wei",76,"Inspecting Xu Huang's perfectly ordered camp at Fancheng",["Xu Chu","Cao Cao","Zhang Liao","Ma Chao"]],["I'm not after riches. I only want to save the people. When you cross the river, please don't slaughter them.","某非爲富貴，但欲救萬民耳。丞相渡江，慎勿殺害。","Pang Tong","龐統","Shu",47,"Leaving Cao Cao's camp after selling him the chain plan",["Guan Yu","Zhuge Liang","Zhao Yun","Pang Tong"]]],[["Just three days and I'll deliver a hundred thousand arrows.","只消三日，便可拜納十萬枝箭。","Zhuge Liang","諸葛亮","Shu",46,"Accepting Zhou Yu's impossible order before Red Cliffs",["Guan Yu","Zhuge Liang","Sun Ce","Xu You"]],["I've long heard your name. Since you understand Heaven's will and the times, why raise an army with no just cause?","久聞公之大名，今幸一會。公既知天命、識時務，何故興無名之兵？","Wang Lang","王朗","Wei",93,"Opening his debate with Zhuge Liang across the battle lines",["Zhang Liao","Wang Lang","Yuan Shao","Xu Chu"]],["That man is so cunning, he keeps me awake day and night!","此人如此多謀，使我曉夜不安矣！","Zhou Yu","周瑜","Wu",49,"After Zhuge Liang slips away from Wu",["Lady Sun","Zhuge Jin","Zhou Yu","Cheng Pu"]]],[["For the sake of this brat, I nearly lost a great general!","爲汝這孺子，幾損我一員大將！","Liu Bei","劉備","Shu",42,"Throwing his baby son to the ground after Zhao Yun rescues him",["Liu Bei","Sun Quan","Xu You","Guan Yu"]],["A mat weaving, sandal making nobody dares to slight me!","織席編屨小輩，安敢輕我！","Yuan Shu","袁術","Rival warlords",21,"Insulting Liu Bei on the battlefield",["Meng Huo","Chen Gong","Yuan Shu","Zhang Song"]],["Don't worry, sir. If I fail to repay this great duty, may I die under ten thousand blades.","大人勿憂。妾若不報大義，死於萬刃之下。","Diao Chan","貂蟬","Han court and others",8,"Accepting the plan to set two men against each other",["Wang Yun","Chen Gong","Kong Rong","Diao Chan"]]],[["In my eyes they're clay chickens and pottery dogs!","以吾觀之，如土雞瓦犬耳！","Guan Yu","關羽","Shu",25,"Looking down on Yuan Shao's army from a hilltop",["Zhang Fei","Guan Yu","Ma Chao","Xu You"]],["You and I are like brothers. Your son is my son. You need say no more.","吾與汝義同兄弟，汝之子即吾之子也，不必多囑。","Zhuge Liang","諸葛亮","Shu",96,"Weeping as he condemns Ma Su",["Guan Yu","Meng Huo","Zhuge Liang","Wei Yan"]],["Walking among corpses, how could I not weep?","行於死柩之中，如何不哭！","Mi Heng","禰衡","Han court and others",23,"Arriving at a farewell party where nobody stands to greet him",["Zuo Ci","Chen Gong","Mi Heng","Ji Ping"]]],[["Your sword may be sharp, but mine isn't blunt either!","汝劍利，吾劍未嘗不利！","Yuan Shao","袁紹","Rival warlords",3,"Drawing his own blade against Dong Zhuo before walking out",["Meng Huo","Zhao Yun","Zhuge Liang","Yuan Shao"]],["I have roamed far and wide choosing a lord to serve, and found none like you. Now I can follow you, my life's wish is fulfilled.","雲奔走四方，擇主而事，未有如使君者。今得相隨，大稱平生。雖肝腦塗地無恨矣！","Zhao Yun","趙雲","Shu",28,"Finally joining Liu Bei for good",["Ma Dai","Liu Bei","Guan Yu","Zhao Yun"]],["I meant to protect the people, and instead I've harmed them! I won't go into Xiangyang!","本欲保民，反害民也！吾不願入襄陽！","Liu Bei","劉備","Shu",41,"When fighting breaks out at the city gates as he arrives",["Lady Mi","Jiang Wei","Liu Chen","Liu Bei"]]],[["Would my tiger of a daughter marry a dog's son? If it weren't for your brother, I'd cut off your head right now!","吾虎女安肯嫁犬子乎！不看汝弟之面，立斬汝首！再休多言！","Guan Yu","關羽","Shu",73,"Rejecting Sun Quan's offer to marry their children",["Liu Bei","Guan Yu","Ma Chao","Huang Zhong"]],["Could it be that the ancients happened to think exactly like me?","莫非古人與我暗合否？","Cao Cao","曹操","Wei",60,"After Zhang Song claims his military treatise is an old book",["Xu Huang","Cao Cao","Zhou Yu","Yang Xiu"]],["Emperor Gaozu set out just three laws and the common people loved him for it. Please ease the punishments to win the people.","昔高祖約法三章，黎民皆感其德。願軍師寬刑省法。以慰民望。","Fa Zheng","法正","Shu",65,"Urging Zhuge Liang to soften his laws in Shu",["Liu Chen","Zhao Yun","Xu Shu","Fa Zheng"]]],[["I worked this out long ago. Go back and tell Zhou Lang to stop playing the beauty trap.","吾已算定多時矣。汝等回去傳示周郎，教休再使美人局手段。","Zhuge Liang","諸葛亮","Shu",55,"Meeting Liu Bei's boats as he escapes Wu with his bride",["Meng Huo","Wang Yun","Zhuge Liang","Zhang Fei"]],["Mengde has Zhang Liao, and I have Gan Xingba. We're evenly matched!","孟德有張遼，孤有甘興霸，足以相敵也。","Sun Quan","孫權","Wu",68,"After a daring night raid on Cao's camp",["Zhou Yu","Sun Quan","Lü Bu","Lu Xun"]],["I am a minister of the great Han guarding the land of the Han. Would I give grain to bandits?","吾乃大漢之臣，守大漢之地，豈有糧米與賊耶！","Kong Rong","孔融","Han court and others",11,"Defying the Yellow Turbans at Beihai",["Kong Rong","Wang Yun","Chen Gong","Lü Bu"]]],[["The sage said that at sudden thunder and fierce wind, a man must change his face. How could I not be afraid?","聖人迅雷風烈必變，安得不畏？","Liu Bei","劉備","Shu",21,"Covering for dropping his chopsticks",["Sun Ce","Liu Bei","Zhao Yun","Yuan Shao"]],["Are you better than Yan Liang and Wen Chou?","汝比顏良、文醜若何？","Guan Yu","關羽","Shu",27,"To Qin Qi, who blocks his way at the Yellow River ford",["Ma Chao","Huang Zhong","Guan Yu","Ma Su"]],["Stop this nonsense! Xuande is my clansman. Would he take my inheritance?","再休亂道！玄德是我同宗，他安肯奪我基業？","Liu Zhang","劉璋","Rival warlords",60,"Ignoring warnings about inviting Liu Bei into Shu",["Liu Zhang","Ju Shou","Ma Teng","Yuan Shao"]]],[["Even if my liver and brains were spilled on the ground, it couldn't repay you!","雲雖肝腦塗地，不能報也！","Zhao Yun","趙雲","Shu",42,"After Liu Bei throws down the baby he rescued",["Zhao Yun","Zhang Fei","Ma Chao","Zhang Liao"]],["What is gained and then lost is the same as never gained. Congratulating me only shames me.","是何言也！得而復失，與不得同。公以此賀我，實足使我愧赧耳。","Zhuge Liang","諸葛亮","Shu",96,"Rejecting praise after his first northern campaign",["Zhuge Liang","Guan Yu","Zhang Fei","Diao Chan"]],["You remember everything after one look. You're a true genius of the realm!","公過目不忘，真天下奇才也！","Yang Xiu","楊修","Wei",60,"After Zhang Song recites a book he read once",["Pang De","Hua Xin","Jia Xu","Yang Xiu"]]],[["I have the imperial seal my late father left me. I'll pledge it as security.","吾有亡父留下傳國玉璽，以爲質當。","Sun Ce","孫策","Wu",15,"Asking Yuan Shu for troops",["Lu Su","Sun Ce","Ma Chao","Lü Bu"]],["If you'd let me do what I wanted at the Xutian hunt, we wouldn't be in this mess.","曩日獵於許田時，若從吾意，可無今日之患。","Guan Yu","關羽","Shu",42,"Grumbling to Liu Bei while fleeing south",["Guan Yu","Zhang Fei","Zhao Yun","Yuan Shao"]],["Do you know how dragons transform, my lord?","使君知龍之變化否？","Cao Cao","曹操","Wei",21,"Making conversation over plum wine as a storm gathers",["Cao Cao","Xun Yu","Guo Jia","Zhang Liao"]]],[["A real man born in troubled times should carry a three foot sword and achieve unmatched deeds. My ambition isn't fulfilled. How can I die?","大丈夫生於亂世，當帶三尺劍立不世之功；今所志未遂，奈何死乎！","Taishi Ci","太史慈","Wu",53,"His last words after an ambush at Hefei",["Sun Quan","Taishi Ci","Chen Gong","Sima Yi"]],["I once mistook Gongsun Zan for a hero. Now I see he's no better than Yuan Shao.","某曩日誤認公孫瓚爲英雄，今觀所爲，亦袁紹等輩耳！","Zhao Yun","趙雲","Shu",7,"Telling Liu Bei why he left his old lord",["Liu Bei","Zhao Yun","Zhuge Liang","Xu You"]],["Is that the man who carried Adou at Changban?","莫非當陽長阪抱阿斗者乎？","Lady Wu","吳國太","Wu",54,"Admiring Zhao Yun at the Ganlu Temple meeting",["Zhou Tai","Zhou Yu","Lady Wu","Lady Sun"]]],[["I'm not laughing at anyone else. I'm laughing that Zhou Yu has no plans and Zhuge Liang has no wits. If I were them, I'd have put an ambush right here.","吾不笑別人，單笑周瑜無謀，諸葛亮少智。若是吾用兵之時，預先在這裏伏下一軍，如之奈何？","Cao Cao","曹操","Wei",50,"Fleeing after Red Cliffs, seconds before an ambush appears",["Yang Xiu","Guan Yu","Cao Cao","Zhuge Liang"]],["We're all going out to fight. What's the Director going to be doing?","我等皆出迎敵，未審軍師卻作何事？","Guan Yu","關羽","Shu",39,"Doubting Zhuge Liang's first battle plan",["Xu Shu","Liu Shan","Lü Bu","Guan Yu"]],["Why is the Chancellor so anxious? This place is so remote, how would Wei troops dare come?","丞相何故多心也？量此山僻之處，魏兵如何敢來！","Ma Su","馬謖","Shu",95,"Arriving at Jieting",["Ma Chao","Guan Yu","Ma Su","Liu Bei"]]],[["I swear to give all my heart and strength to wipe out the traitors of the Han and recover the Central Plains. I will bend my body to the task until I die!","誓竭力盡心，剿滅漢賊，恢復中原，鞠躬盡瘁，死而後已！","Zhuge Liang","諸葛亮","Shu",102,"Weeping at Liu Bei's shrine before another northern campaign",["Zhang Fei","Zhang Liao","Yang Xiu","Zhuge Liang"]],["Light plenty of torches! We fight on through the night!","多點火把，安排夜戰！","Zhang Fei","張飛","Shu",65,"Refusing to stop his duel with Ma Chao at Jiameng Pass",["Ma Dai","Zhang Liao","Zhang Fei","Liu Bei"]],["I can go decades without eating and it does me no harm. Or I can eat a thousand sheep a day.","我數十年不食，亦不妨；日食千羊，亦能盡。","Zuo Ci","左慈","Han court and others",68,"Showing off his powers in front of Cao Cao",["Zuo Ci","Diao Chan","Emperor Xian","Hua Xiong"]]],[["The only heroes in the land today are you, my lord, and I.","今天下英雄，惟使君與操耳！","Cao Cao","曹操","Wei",21,"Over plum wine with Liu Bei, who drops his chopsticks in shock",["Yang Xiu","Cao Cao","Zhao Yun","Sun Ce"]],["A wild scholar! What use is he?","狂士也，用之何益？","Sun Quan","孫權","Wu",57,"Rejecting the ugly Pang Tong after meeting him",["Zhuge Jin","Pang Tong","Sun Quan","Sun Ce"]],["You use the name of Han chancellor, but you're a traitor to the Han! Your crimes fill the heavens, worse than Wang Mang and Dong Zhuo!","汝託名漢相，實爲漢賊！惡罪彌天，甚於莽、卓，乃反誣人造反耶！","Yuan Shao","袁紹","Rival warlords",30,"Facing Cao Cao at Guandu",["Yuan Shao","Tian Feng","Zhang Song","Zhang Ren"]]],[["My plan has failed. It is Heaven's will!","吾計不成，乃天命也！","Jiang Wei","姜維","Shu",119,"His last words in Chengdu after the fall of Shu",["Jiang Wei","Ma Chao","Huang Zhong","Liu Bei"]],["I may be in a hopeless spot, but I see death as going home.","此言特說我也！吾今雖處絕地，視死如歸。汝當速去，吾即下山迎戰。","Guan Yu","關羽","Shu",25,"Surrounded on a hill outside Xiapi",["Xu Shu","Chen Gong","Wei Yan","Guan Yu"]],["The gods protect me. What do I have to fear?","神人佑我，吾何懼焉！","Sun Ce","孫策","Wu",15,"Visiting a temple right next to the enemy camp",["Kan Ze","Cheng Pu","Lü Meng","Sun Ce"]]],[["This boy wants to set me on top of a furnace!","是兒欲使吾居爐火上耶！","Cao Cao","曹操","Wei",78,"Reading Sun Quan's letter urging him to take the throne",["Dong Zhuo","Cao Cao","Zhou Yu","Xu You"]],["Let me go, I'll gather my men and we'll settle it properly. If you can catch me again, then I'll submit.","汝放我回去，再整軍馬，共決雌雄；若能再擒吾，吾方服也。","Meng Huo","孟獲","Rival warlords",87,"After his first capture",["Yuan Shu","Guan Yu","Tian Feng","Meng Huo"]],["You'd have my lord bend the knee to that traitor of the state?","汝教吾主屈膝受辱於國賊乎！","Lu Su","魯肅","Wu",44,"Furious when Zhuge Liang pretends to agree with surrender",["Lady Sun","Sun Quan","Gan Ning","Lu Su"]]],[["I want him to take them. I lose a few wooden oxen and gliding horses, and soon I'll get plenty of supplies in return.","吾正要他搶去。我只費了幾匹木牛流馬，卻不久便得軍中許多資助也。","Zhuge Liang","諸葛亮","Shu",102,"After the enemy captures his transport machines",["Wang Yun","Sun Quan","Zhuge Liang","Zhang Fei"]],["If I don't kill this traitor today, he'll bring disaster later.","今日不殺此賊，後必爲禍。","Guan Yu","關羽","Shu",20,"Reaching for his blade during the hunt at Xutian",["Zhuge Liang","Pang Tong","Liu Shan","Guan Yu"]],["I heard of your righteousness, my lord, and came to heal you. Why would I want a reward?","某聞君侯高義，特來醫治，豈望報乎！","Hua Tuo","華佗","Han court and others",75,"Refusing payment from Guan Yu",["Hua Tuo","Emperor Xian","Ji Ping","He Jin"]]],[["How could I compare with Liang? I'm the glow of a firefly and he is the bright moon.","庶安敢比亮？庶如螢火之光，亮乃皓月之明也。","Xu Shu","徐庶","Shu",39,"Answering Cao Cao's question about Zhuge Liang",["Zhao Yun","Cao Cao","Yuan Shao","Xu Shu"]],["Life and death are fated. What's there to cry about? The next man who cries gets his head cut off!","生死有命，何哭之有？如再哭者立斬！","Cao Cao","曹操","Wei",50,"Forcing his men through the mud of Huarong Road",["Cao Cao","Cao Pi","Liu Bei","Xu Chu"]],["Would a loyal subject ever serve two lords?","忠臣豈肯事二主乎？","Zhang Ren","張任","Rival warlords",64,"Refusing to surrender to Liu Bei after his capture",["Tian Feng","Shen Pei","Zhang Ren","Yuan Shu"]]],[["This boy is the least trustworthy of them all!","是兒最無信者！","Lü Bu","呂布","Han court and others",19,"Glaring at Liu Bei after Cao Cao decides on his execution",["Diao Chan","Lü Bu","Zhuge Liang","Dong Zhuo"]],["Here are the sword and seal. Anyone who disobeys will be executed!","劍印在此，違令者斬！","Zhuge Liang","諸葛亮","Shu",39,"Taking command for the first time before Bowang",["Zhuge Liang","Zhang Fei","Sun Ce","Wei Yan"]],["I may be from beyond the borders, but I don't use tricks like you. Why should I submit?","吾雖是化外之人，不似丞相專施詭計，吾如何肯服？","Meng Huo","孟獲","Rival warlords",89,"After his fourth capture",["Meng Huo","Tian Feng","Liu Qi","Yuan Shu"]]],[["Liang has always been careful and never takes risks. If he's thrown open the gates, there must be an ambush. Retreat at once!","亮平生謹慎，不曾弄險。今大開城門，必有埋伏。我兵若進，中其計也。汝輩豈知？宜速退。","Sima Yi","司馬懿","Wei",95,"Pulling back from the Empty Fort",["Sima Yi","Lü Bu","Zhuge Liang","Zhang Liao"]],["Lord Guan has shaken the whole realm and never met his match. Now he faces Lingming, a real rival.","關某威震華夏，未逢對手；今遇令明，真勁敵也。","Cao Cao","曹操","Wei",74,"Watching Pang De fight Guan Yu",["Jiang Gan","Cao Cao","Wang Yun","Cao Pi"]],["That pedant ruined everything! I couldn't kill the traitor for the state. It's Heaven's will!","豎儒誤我大事！我不能爲國殺賊，是乃天也！","Ma Teng","馬騰","Rival warlords",57,"Captured in the capital after his plot is betrayed",["Meng Huo","Liu Biao","Liu Qi","Ma Teng"]]],[["If I lose, cut off my head.","如不勝，請斬某頭。","Guan Yu","關羽","Shu",5,"Volunteering to face Hua Xiong in front of the coalition lords",["Lü Bu","Zhao Yun","Huang Zhong","Guan Yu"]],["Ah Man, without me could you ever have got through this gate?","阿瞞，汝不得我，安能入此門？","Xu You","許攸","Wei",33,"Calling Cao Cao by his childhood name after the fall of Ye",["Xu You","Huang Zhong","Zhang He","Sima Yi"]],["Sima Yi sent you to fake a surrender and work from inside. Did you think you could fool me? Tell the truth or lose your head!","司馬懿令汝來詐降，於中取事，卻如何瞞得我過！若不實說，必然斬汝！","Zhuge Liang","諸葛亮","Shu",102,"Exposing a spy from Sima Yi",["Ma Dai","Zhuge Liang","Zhang Fei","Pang Tong"]]],[["I swear Wu and I will never share the same sun and moon!","孤與東吳，誓不同日月也！","Liu Bei","劉備","Shu",78,"After Guan Yu's death",["Zhao Yun","Zhang Liao","Liu Bei","Ma Chao"]],["Of my five sons, this one is the most remarkable. If anything happens to him, my life is over.","五子中惟此子生得最異，倘有疏虞，吾命休矣。","Yuan Shao","袁紹","Rival warlords",24,"Refusing to attack while his youngest son is ill",["Yuan Shu","Tian Feng","Yang Xiu","Yuan Shao"]],["You've led armies since you were young. Don't you know to watch for fire in narrow places?","汝自幼用兵，豈不知狹處須防火攻？","Cao Cao","曹操","Wei",40,"Scolding Xiahou Dun after the defeat at Bowang",["Xu You","Hua Xin","Jia Xu","Cao Cao"]]],[["Wei Yan has a reverse bone at the back of his head. He's bound to rebel one day, so I'll cut him down now.","吾觀魏延腦後有反骨，久後必反，故斬之以絕禍根。","Zhuge Liang","諸葛亮","Shu",53,"Ordering Wei Yan's execution the moment he surrenders at Changsha",["Zhao Yun","Dong Zhuo","Zhuge Liang","Pang Tong"]],["I was thinking about Yuan Benchu and Liu Jingsheng, and their sons.","思袁本初、劉景升父子也。","Jia Xu","賈詡","Wei",68,"Hinting to Cao Cao which son should be heir",["Xu You","Guo Jia","Zhang He","Jia Xu"]],["Lord Guan may have wings to fly to the sky, but he'll never escape my net!","卦象正合某之機也。關公雖有沖天之翼，飛不出吾羅網矣！","Lü Meng","呂蒙","Wu",76,"Closing in on Guan Yu at Maicheng",["Zhou Yu","Lady Wu","Lü Meng","Taishi Ci"]]],[["I am Zhao Zilong of Changshan!","吾乃常山趙子龍也！","Zhao Yun","趙雲","Shu",41,"Cutting through Cao Cao's army at Changban",["Guan Yu","Zhao Yun","Lu Su","Ma Chao"]],["Bow your head, keep to your place and wait for Heaven's moment. You can't fight fate.","屈身守分，以待天時，不可與命爭也。","Liu Bei","劉備","Shu",15,"Persuading his brothers to accept Lü Bu's terms",["Zhou Yu","Ma Dai","Liu Bei","Pang Tong"]],["When we fought at Shenting, if you had captured me, would you have killed me?","神亭相戰之時，若公獲我，還相害否？","Sun Ce","孫策","Wu",15,"To Taishi Ci after capturing him",["Cheng Pu","Sun Ce","Zhou Tai","Lü Meng"]]],[["They died and became angry ghosts. How can I kill more living people? I have my own idea.","本爲人死而成怨鬼，豈可又殺生人耶？吾自有主意。","Zhuge Liang","諸葛亮","Shu",91,"Refusing to make human sacrifices at the Lu River",["Liu Bei","Yang Xiu","Chen Gong","Zhuge Liang"]],["I'm a real man nearly sixty years old. What would I regret about dying?","吾大丈夫，年近六旬，即死何憾！","Guan Yu","關羽","Shu",73,"After a dream of a black boar biting his foot",["Zhang Fei","Guan Yu","Zhao Yun","Cao Cao"]],["Yunchang has taken his army to besiege Fancheng. We can strike while he's away and seize Jing Province.","今雲長提兵圍樊城，可乘其遠出，襲取荊州。","Lü Meng","呂蒙","Wu",75,"Pitching the plan that dooms Guan Yu",["Lü Meng","Kan Ze","Lu Su","Sun Quan"]]],[["If I don't avenge my brother, what's ten thousand li of land worth?","朕不爲弟報仇，雖有萬里江山，何足爲貴？","Liu Bei","劉備","Shu",81,"Rejecting advice not to attack Wu",["Liu Bei","Sima Yi","Guan Yu","Zhang Fei"]],["Spent half your life fighting and you're still scared of weapons?","廝殺半生，尚懼兵器乎？","Lady Sun","孫夫人","Wu",55,"Laughing at her new husband's nerves on their wedding night",["Huang Gai","Lu Su","Lady Sun","Diao Chan"]],["I've fallen for a trick again. I'll die with my eyes open!","吾今誤中詭計，死不瞑目！","Meng Huo","孟獲","Rival warlords",89,"Caught in yet another ambush",["Yuan Shu","Ju Shou","Liu Biao","Meng Huo"]]],[["That mat weaving brat, how dare he! I swear I'll destroy him!","織席小兒，安敢如此！吾誓滅之！","Cao Cao","曹操","Wei",73,"Hearing Liu Bei has made himself King of Hanzhong",["Cao Cao","Zhang Liao","Yang Xiu","Lü Bu"]],["My life was meant to end. It isn't Wenchang's fault.","此吾命當絕，非文長之過也。","Zhuge Liang","諸葛亮","Shu",104,"Stopping an officer from killing Wei Yan for knocking over the lamp",["Zhuge Liang","Sun Quan","Xu Shu","Liu Shan"]],["If you don't listen to my advice, the campaign will go badly.","若不聽臣良言，出師不利。","Tian Feng","田豐","Rival warlords",25,"Begging Yuan Shao not to march south",["Zhang Song","Tian Feng","Shen Pei","Meng Huo"]]],[["When we swore our oath in the peach garden we vowed to die together. Now Yunchang is gone, how can I enjoy riches alone?","孤與關、張二弟桃園結義時，誓同生死。今雲長已亡，孤豈能獨享富貴乎？","Liu Bei","劉備","Shu",78,"Mourning Guan Yu",["Liu Bei","Lü Bu","Guan Yu","Sun Ce"]],["I came to you in good faith and you lie to me like this. Is this what I deserve?","吾以誠相投，而公見欺如是，豈吾所望哉！","Xu You","許攸","Wei",30,"After Cao Cao keeps lying about his grain",["Zhuge Liang","Deng Ai","Cao Cao","Xu You"]],["I have the courage of ten thousand men. Why would I fear anyone? Tonight under the moon is perfect for moving the grain carts.","吾有萬夫之勇，豈懼他人哉！今夜乘著月色，正好使糧車行走。","Xu Chu","許褚","Wei",72,"Ignoring the danger at Hanzhong",["Xiahou Dun","Pang De","Cheng Yu","Xu Chu"]]],[["He's just a villager. Why go yourself, brother? Send someone to fetch him.","量一村夫，何必哥哥自去，可使人喚來便了。","Zhang Fei","張飛","Shu",37,"On the visits to Zhuge Liang's cottage",["Liu Bei","Zhang Fei","Zhao Yun","Diao Chan"]],["I have a precious blade, which I present to you, Chancellor.","操有寶刀一口，獻上恩相。","Cao Cao","曹操","Wei",4,"Thinking fast when Dong Zhuo spots him drawing a sword",["Zhang Fei","Cao Pi","Jiang Gan","Cao Cao"]],["Liu Bei said that to tease me for not being used to horses.","劉備此言，戲我不慣乘馬耳。","Sun Quan","孫權","Wu",54,"After Liu Bei's remark about southerners and boats",["Sun Quan","Huang Gai","Lady Wu","Lu Su"]]],[["I'm nothing special. My brother Zhang Yide can take a general's head in the middle of a million men as easily as taking something from a bag.","某何足道哉！吾弟張翼德，於百萬軍中取上將之頭，如探囊取物耳。","Guan Yu","關羽","Shu",25,"Modestly brushing off praise after Baima",["Guan Yu","Liu Bei","Ma Chao","Diao Chan"]],["My brother is brave all right, but he doesn't think things through.","吾弟勇則勇矣，惜失於計較。","Liu Bei","劉備","Shu",42,"After Zhang Fei destroys the bridge at Changban",["Xu Shu","Ma Chao","Liu Bei","Zhuge Liang"]],["I'm just an ordinary talent. What clever plans would I have?","亮乃碌碌庸才，安有妙計？","Zhuge Liang","諸葛亮","Shu",46,"Being modest when Zhou Yu asks for advice",["Ma Chao","Zhang Fei","Zhuge Liang","Liu Shan"]]],[["I came to persuade him and he ended up persuading me!","我來說他，反被他說了我也。","Zhuge Jin","諸葛瑾","Wu",44,"After failing to win his brother over to Wu",["Zhuge Jin","Zhou Yu","Pang Tong","Meng Huo"]],["We haven't seen each other in years and I came to catch up. Why suspect me of being a persuader?","吾久別足下，特來敘舊，奈何疑我作說客也？","Jiang Gan","蔣幹","Wei",45,"Taken aback by Zhou Yu's greeting",["Dong Zhuo","Jiang Gan","Jia Xu","Zhang He"]],["I have received great kindness from the house of Sun. Even if my liver and brains were spilled on the ground, I'd have no regrets.","某受孫氏厚恩，雖肝腦塗地，亦無怨悔。","Huang Gai","黃蓋","Wu",46,"Volunteering for the beating ruse",["Zhou Yu","Gan Ning","Huang Gai","Lu Su"]]],[["Your talent is ten times Cao Pi's. You'll surely secure the state. If my son can be helped, help him. If he has no talent, you can rule Chengdu yourself.","君才十倍曹丕，必能安邦定國，終定大事。若嗣子可輔則輔之；如其不才，君可自爲成都之主。","Liu Bei","劉備","Shu",85,"To Zhuge Liang on his deathbed at Baidi",["Guan Yu","Xu You","Chen Gong","Liu Bei"]],["While Zhou Yu was alive I wasn't afraid. Now he's dead, what's there to worry about?","瑜在之日，亮猶不懼；今瑜已死，又何患乎？","Zhuge Liang","諸葛亮","Shu",57,"Deciding to attend Zhou Yu's funeral in Wu",["Zhuge Liang","Ma Dai","Zhang Fei","Sun Quan"]],["Getting Yunchang would be worth ten times Yan Liang and Wen Chou.","吾得雲長，勝顏良、文醜十倍也。","Yuan Shao","袁紹","Rival warlords",26,"Excited at the idea of luring Guan Yu over",["Meng Huo","Shen Pei","Liu Qi","Yuan Shao"]]],[["Kongming is still alive! I've rushed in too deep and fallen for his trick!","孔明尚在！吾輕入重地，墮其計矣！","Sima Yi","司馬懿","Wei",104,"Fleeing from a wooden statue of Zhuge Liang",["Sima Yi","Diao Chan","Zhang Liao","Zhou Yu"]],["My plan has failed. How can I face my lord?","吾計不成，有何面目去見吳侯！","Zhou Yu","周瑜","Wu",55,"After Liu Bei escapes Wu with his new wife",["Cao Cao","Lü Meng","Huang Gai","Zhou Yu"]],["People say Liu Xuande is generous and hospitable, and it's true.","人言劉玄德寬仁愛客，今果如此。","Zhang Song","張松","Rival warlords",60,"After being met at the border by Zhao Yun and Guan Yu",["Zhang Song","Zhang Ren","Ju Shou","Zhang Xiu"]]],[["Yuan Shao looks stern but has no guts. He loves scheming but can't decide. No hero.","袁紹色厲膽薄，好謀無斷；幹大事而惜身，見小利而忘命，非英雄也。","Cao Cao","曹操","Wei",21,"Rejecting another of Liu Bei's candidates",["Cao Cao","Diao Chan","Sun Ce","Sima Yi"]],["We've sworn brotherhood, so your sister in law is my sister in law. How could I do something so wrong?","吾既與汝結爲兄弟，汝嫂即吾嫂也，豈可作此亂人倫之事乎！","Zhao Yun","趙雲","Shu",52,"Refusing Zhao Fan's offer of his widowed sister in law",["Xu You","Liu Shan","Huang Zhong","Zhao Yun"]],["At this moment I'm also afraid to hit the rat for fear of breaking the vase.","我於此時亦『投鼠忌器』耳。","Liu Bei","劉備","Shu",42,"Explaining why he didn't kill Cao Cao at the Xutian hunt",["Pang Tong","Ma Chao","Zhao Yun","Liu Bei"]]],[["You are surnamed Lü, he is surnamed Dong. When he threw his halberd at you, where was the love between father and son?","將軍自姓呂，太師自姓董。擲戟之時，豈有父子情耶？","Wang Yun","王允","Han court and others",9,"Persuading Lü Bu to kill Dong Zhuo",["Yang Xiu","Wang Yun","Chen Gong","Zhuge Liang"]],["Sima Zhao plans to usurp the throne and everyone knows it. I won't sit here waiting to be deposed. Help me strike him!","司馬昭將懷篡逆，人所共知。朕不能坐受廢辱，卿等可助朕討之！","Cao Mao","曹髦","Wei",114,"The young Wei emperor, before leading his servants against Sima Zhao",["Xiahou Dun","Sun Ce","Xu Huang","Cao Mao"]],["I have failed the state!","我誤國家之大事也！","Zhuge Liang","諸葛亮","Shu",104,"Weeping as he hears Wei Yan has disrupted his ritual",["Zhuge Liang","Zhang Fei","Liu Chen","Liu Shan"]]],[["Don't worry. I have my halberd and Red Hare. Who dares come near me?","汝無憂慮。吾有畫戟、赤兔馬，誰敢近我！","Lü Bu","呂布","Han court and others",19,"Reassuring his wife during the siege of Xiapi",["Pang Tong","Lü Bu","Ma Chao","Chen Gong"]],["I just hope he hits it!","只願他射得中便好！","Liu Bei","劉備","Shu",16,"Silently praying as Lü Bu lines up his shot at the halberd",["Liu Bei","Ma Chao","Sun Quan","Huang Zhong"]],["People say Lord Guan is a hero. Today I believe it.","人言關公英雄，今日方信也。","Pang De","龐德","Wei",74,"After a hundred bouts with Guan Yu",["Deng Ai","Cao Ren","Sima Yi","Pang De"]]],[["He doesn't forget his old master and comes and goes in the open. A true man! You should all follow his example.","不忘故主，來去明白，真丈夫也。汝等皆當效之。","Cao Cao","曹操","Wei",27,"Hearing Guan Yu has left to find Liu Bei",["Cao Cao","Wang Yun","Xu You","Sun Ce"]],["Lü Bu may lack strategy, but he isn't as sly and wicked as you.","布雖無謀，不似你詭詐奸險。","Chen Gong","陳宮","Han court and others",19,"Defending his choice of master to Cao Cao",["Dong Zhuo","Hua Tuo","Chen Gong","Cao Cao"]],["Zhou Gongjin only trusts his own ability and thinks nothing of us. Now I've been humiliated, I'm ashamed to face anyone in Jiangdong!","周公瑾只自恃其能，全不以我等爲念。我今被辱，羞見江左諸人！","Gan Ning","甘寧","Wu",47,"Pretending to be bitter so the Cai brothers believe him",["Gan Ning","Lü Meng","Zhuge Jin","Zhang Zhao"]]],[["Having Kongming is like a fish finding water. Not another word, you two.","吾得孔明，猶魚之得水也。兩弟勿復多言。","Liu Bei","劉備","Shu",39,"Silencing Guan Yu and Zhang Fei, jealous of the newcomer",["Liu Bei","Zhuge Liang","Yang Xiu","Ma Chao"]],["Dong Zhuo has been executed and everyone is celebrating. Who dares weep for him?","董卓伏誅，士民莫不稱賀，此何人獨敢哭耶！","Wang Yun","王允","Han court and others",9,"Catching the scholar Cai Yong mourning the dead tyrant",["Diao Chan","Lü Bu","Zhou Yu","Wang Yun"]],["Huang Zu is my closest friend. Abandoning him would be wrong.","吾與黃祖心腹之交，捨之不義。","Liu Biao","劉表","Rival warlords",8,"Choosing to trade Sun Jian's body for his captured general",["Liu Biao","Shen Pei","Tian Feng","Yuan Shao"]]],[["Zilong is dead! The state has lost a pillar, and I have lost an arm!","子龍身故，國家損一棟樑，吾去一臂也！","Zhuge Liang","諸葛亮","Shu",97,"On the death of Zhao Yun",["Zhuge Liang","Ma Chao","Yang Xiu","Lü Bu"]],["This is the thousand li colt of my family!","此吾家千里駒也！","Cao Cao","曹操","Wei",56,"Praising his young kinsman Cao Xiu at the archery contest",["Cao Cao","Sun Ce","Cao Pi","Sima Yi"]],["Zhou Yu is a man of great refinement. Words can't move him.","周瑜雅量高致，非言詞所能動也。","Jiang Gan","蔣幹","Wei",45,"Reporting back to Cao Cao after his mission fails",["Cao Cao","Jia Xu","Wang Lang","Jiang Gan"]]],[["Any official or general who mentions surrendering to Cao again will end up like this desk!","諸官將有再言降操者，與此案同！","Sun Quan","孫權","Wu",44,"Slashing his desk in front of the court",["Lu Su","Pang Tong","Sun Quan","Chen Gong"]],["The people suffer this disaster for my sake alone. How can I go on living?","爲吾一人，而使百姓遭此大難，吾何生哉！","Liu Bei","劉備","Shu",41,"Watching the refugees who follow him being cut down",["Ma Su","Zhao Yun","Huang Zhong","Liu Bei"]],["This shows true mastery of naval warfare!","此深得水軍之妙也！","Zhou Yu","周瑜","Wu",45,"Spying on Cao Cao's river camp",["Huang Gai","Zhou Yu","Lady Sun","Lu Xun"]]],[["Who dares to kill me?","誰敢殺我？","Wei Yan","魏延","Shu",105,"Shouting three times outside Nanzheng after rebelling",["Lü Bu","Pang Tong","Sun Ce","Wei Yan"]],["I've only got two thousand five hundred men. If I abandon the city we won't get far. We'd be caught for sure.","吾兵止有二千五百，若棄城而走，必不能遠遁。得不爲司馬懿所擒乎？","Zhuge Liang","諸葛亮","Shu",95,"Explaining his choice to his officers as Sima Yi approaches",["Guan Yu","Zhuge Liang","Diao Chan","Xu Shu"]],["With the least benevolent attacking the most benevolent, how can he fail to lose?","以至不仁伐至仁，安得不敗乎！","Kong Rong","孔融","Han court and others",40,"The remark that gets him executed",["Emperor Xian","Kong Rong","Wang Yun","Sima Hui"]]],[["When you tie up a tiger, you can't help tying it tight.","縛虎不得不急。","Cao Cao","曹操","Wei",19,"Replying to a prisoner who complains his ropes are too tight",["Xu You","Huang Zhong","Yang Xiu","Cao Cao"]],["This is the finest landscape under heaven!","此乃天下第一江山也！","Liu Bei","劉備","Shu",54,"Admiring the view from Ganlu Temple",["Guan Yu","Liu Bei","Zhao Yun","Wei Yan"]],["What if Cao's whole army comes out?","倘曹兵齊出，如之奈何？","Lu Su","魯肅","Wu",46,"Shaking on a straw boat in the fog",["Sun Quan","Lu Su","Lady Sun","Huang Gai"]]],[["To me, Yan Liang looks like a man with a price tag on his own head!","吾觀顏良，如插標賣首耳！","Guan Yu","關羽","Shu",25,"Before riding out and killing Yan Liang at Baima",["Huang Zhong","Pang Tong","Guan Yu","Ma Chao"]],["Jiang Wei has truly mastered Kongming's methods! His army doesn't panic at night, his generals don't flinch at surprises. A real general!","姜維深得孔明之法！兵在夜而不驚，將聞變而不亂：真將材也！","Deng Ai","鄧艾","Wei",113,"Studying Jiang Wei's camp",["Cao Pi","Zhang He","Zhou Yu","Deng Ai"]],["Sima Yi is no ordinary man, and his vanguard Zhang He is one of Wei's best. I fear you're no match for them.","司馬懿非等閒之輩；更有先鋒張郃，乃魏之名將：恐汝不能敵之。","Zhuge Liang","諸葛亮","Shu",95,"Warning Ma Su before Jieting",["Ma Dai","Zhuge Liang","Yan Yan","Xu Shu"]]],[["If I can't make you my wife in this life, I'm no hero!","我今生不能以汝爲妻，非英雄也！","Lü Bu","呂布","Han court and others",8,"In the garden of the Phoenix Pavilion",["Lü Bu","Dong Zhuo","Zhang Fei","Sima Yi"]],["When I first met Zilong I couldn't bear to part from him. Now at last we meet again!","吾初見子龍，便有留戀不捨之情。今幸得相遇！","Liu Bei","劉備","Shu",28,"Reunited with Zhao Yun after years apart",["Liu Shan","Zhuge Liang","Zhang Liao","Liu Bei"]],["Liu Zhang may be of the imperial clan, but he's just a dog guarding a door. Hardly a hero.","劉璋雖係宗室，乃守戶之犬耳，何足爲英雄？","Cao Cao","曹操","Wei",21,"Running through the warlords over plum wine",["Xun Yu","Xu You","Cao Cao","Xiahou Dun"]]],[["In my whole life as a doctor I've never seen anything like it. You are truly a god, my lord!","某爲醫一生，未嘗見此。君侯真天神也！","Hua Tuo","華佗","Han court and others",75,"After scraping the poison from Guan Yu's bone while he plays go",["Lü Bu","Zhuge Liang","Hua Tuo","Sun Quan"]],["An army isn't about numbers, it's about surprise and wits. With Your Majesty's blessing I'll capture Gongsun Yuan for you.","兵不在多，在能設奇用智耳。臣託陛下洪福，必擒公孫淵以獻陛下。","Sima Yi","司馬懿","Wei",106,"Volunteering for the Liaodong campaign",["Pang De","Dong Zhuo","Xiahou Dun","Sima Yi"]],["Rejoicing over invading someone else's land is not how a benevolent army behaves.","伐人之國而以爲樂，非仁者之兵也。","Pang Tong","龐統","Shu",62,"Rebuking Liu Bei for celebrating at Fu",["Pang Tong","Ma Dai","Lady Mi","Ma Su"]]],[["Kongming's divine plans! I'm no match for him!","孔明神機妙算，吾不如也！","Zhou Yu","周瑜","Wu",46,"After the straw boats bring back a hundred thousand arrows",["Sun Quan","Lu Su","Zhao Yun","Zhou Yu"]],["I ride alone across the whole realm. Why should I worry about Cao Cao?","吾匹馬縱橫天下，何愁曹操？待其下寨，吾自擒之！","Lü Bu","呂布","Han court and others",11,"Ignoring advice before the fight for Puyang",["Chen Gong","Liu Bei","Zuo Ci","Lü Bu"]],["I am carrying out Heaven's justice. How could I bear to slaughter the people?","吾替天行道，安忍殺戮人民？","Cao Cao","曹操","Wei",47,"Promising Pang Tong to spare the people of the south",["Xu Huang","Hua Xin","Cao Mao","Cao Cao"]]],[["Now you're emperor, you've forgotten the peach garden oath! Why haven't you avenged our brother?","陛下今日爲君，早忘了桃園之誓！二兄之仇如何不報？","Zhang Fei","張飛","Shu",81,"Weeping before Liu Bei after Guan Yu's death",["Zhang Fei","Pang Tong","Ma Chao","Sun Ce"]],["The green hills never age and the blue waters flow forever. When this is done, I'll repay you well.","青山不老，綠水長存。他日事成，必當厚報。","Liu Bei","劉備","Shu",60,"Saying farewell to Zhang Song after receiving his map of Shu",["Sima Yi","Zhuge Liang","Liu Bei","Ma Dai"]],["Meng Da will surely die at Sima Yi's hands!","孟達必死於司馬懿之手矣！","Zhuge Liang","諸葛亮","Shu",94,"Throwing down Meng Da's letter in despair",["Huang Zhong","Ma Chao","Xu Shu","Zhuge Liang"]]],[["A hero holds great ambitions in his chest and fine plans in his belly. He can hide the universe within him and swallow heaven and earth.","夫英雄者，胸懷大志，腹有良謀，有包藏宇宙之機，吞吐天地之志者也。","Cao Cao","曹操","Wei",21,"Defining a true hero to Liu Bei",["Dong Zhuo","Yang Xiu","Diao Chan","Cao Cao"]],["Who sends someone a draft? Uncle must have blotted it out so I wouldn't see the details!","豈有以草稿送與人耶？必是叔父怕我知了詳細，先改抹了。","Ma Chao","馬超","Shu",59,"Reading Han Sui's smudged letter from Cao Cao",["Lu Su","Zhuge Liang","Huang Zhong","Ma Chao"]],["Bingzhou is close to the northern frontier, so prepare well.","并州近朔方，好爲之備。","Sima Yi","司馬懿","Wei",106,"Feigning confusion before a spy who says he's going to Jingzhou",["Sima Yi","Deng Ai","Zhang Liao","Cao Pi"]]],[["When I take your horses you're furious. When you took my brother's Xuzhou you said nothing!","我奪你馬你便惱，你奪我哥哥的徐州，便不說了！","Zhang Fei","張飛","Shu",16,"Shouting back at Lü Bu over stolen horses",["Zhang Fei","Huang Zhong","Zhao Yun","Ma Chao"]],["His insight is ten times mine. If I don't get rid of him now, he'll be the ruin of our state!","此人見識勝吾十倍，今不除之，後必爲我國之禍！","Zhou Yu","周瑜","Wu",45,"Seething after Zhuge Liang sees through his plan",["Zhou Yu","Sun Quan","Liu Bei","Zhang Zhao"]],["That big eared thief! How dare he!","大耳賊！焉敢如此！","Yuan Shao","袁紹","Rival warlords",26,"Hearing his general Wen Chou has been killed by Guan Yu",["Liu Qi","Shen Pei","Yuan Shao","Zhang Song"]]],[["The box clearly says one mouthful per person. How could we disobey the Chancellor?","盒上明書一人一口酥，豈敢違丞相之命乎？","Yang Xiu","楊修","Wei",72,"Explaining why the pastry gift was eaten",["Sun Ce","Yang Xiu","Sima Yi","Zhuge Liang"]],["The pedant's tongue was a sword, and in the end it killed him!","腐儒舌劍，反自殺矣！","Cao Cao","曹操","Wei",23,"Laughing on hearing of Mi Heng's death",["Yang Xiu","Cao Cao","Deng Ai","Zhang Liao"]],["I hear you swore at the peach garden to live and die with Imperial Uncle Liu. So he is you. How can you dodge the question?","某聞君侯與皇叔桃園結義，誓同生死。皇叔即君侯也，何得推託乎？","Lu Su","魯肅","Wu",66,"Pressing Guan Yu at the Single Sword Meeting",["Huang Gai","Lu Xun","Lu Su","Kan Ze"]]],[["That old traitor and I cannot both live!","吾與老賊誓不兩立！","Zhou Yu","周瑜","Wu",44,"Vowing war after hearing Cao Cao wants the Qiao sisters",["Zhang Liao","Lu Su","Meng Huo","Zhou Yu"]],["An empty reputation, a mediocre talent! If Kongming uses men like this, how can he not fail?","徒有虛名，乃庸才耳！孔明用如此人物，如何不誤事！","Sima Yi","司馬懿","Wei",95,"Seeing the Shu army camped on a hill at Jieting",["Zhang Fei","Xu You","Sima Yi","Cao Pi"]],["Ungrateful wretch! The Chancellor spared your life and you rebel again. Aren't you ashamed?","無義背恩之徒！吾丞相饒汝性命，今又背反，豈不自羞？","Ma Dai","馬岱","Shu",88,"To a southern chief who turns on Zhuge Liang",["Liu Chen","Yan Yan","Zhang Fei","Ma Dai"]]],[["If I'm to have a son, let him be like Sun Zhongmou! Liu Jingsheng's sons are mere pigs and dogs.","生子當如孫仲謀！若劉景升兒子，豚犬耳！","Cao Cao","曹操","Wei",61,"Watching Sun Quan's fleet in perfect order at Ruxu",["Sima Yi","Cao Cao","Yang Xiu","Xu You"]],["Why does Your Highness rate Guan Yu so highly? This time I'll knock thirty years off his reputation.","大王何重視關某也？吾料此去，當挫關某三十年之聲價。","Pang De","龐德","Wei",74,"Before facing Guan Yu at Fancheng",["Pang De","Sima Yi","Xu You","Cao Cao"]],["General, don't underestimate Liu Xuande. With Zhuge Liang helping him, he's like a tiger that has grown wings.","將軍勿輕視劉玄德。今玄德得諸葛亮爲輔，如虎生翼矣。","Xu Shu","徐庶","Shu",39,"Warning Cao Cao's generals",["Liu Shan","Ma Chao","Liu Chen","Xu Shu"]]],[["Director, why do you look down on me? I once held off Cao Cao's million men alone. Why would I fear one Ma Chao?","軍師何故小覷吾！吾曾獨拒曹操百萬之兵，豈愁馬超一匹夫乎！","Zhang Fei","張飛","Shu",65,"Demanding to fight Ma Chao",["Pang Tong","Zhang Fei","Chen Gong","Ma Chao"]],["I've followed the Martial General across the southeast through three generations. Where were you then?","吾自隨破虜將軍，縱橫東南，已歷三世，那有你來？","Huang Gai","黃蓋","Wu",46,"Mocking Zhou Yu in front of the whole camp",["Zhou Yu","Lady Wu","Xu You","Huang Gai"]],["That's the talk of a pedant! Jiangdong has stood for three generations. How can we throw it away in one day?","此迂儒之論也！江東自開國以來，今歷三世，安忍一旦廢棄？","Zhou Yu","周瑜","Wu",44,"Answering those who want to surrender",["Zhou Yu","Kan Ze","Lu Xun","Sun Quan"]]],[["If you won't come out, what will become of the people?","先生不出，如蒼生何！","Liu Bei","劉備","Shu",38,"Weeping during his third visit to the thatched cottage",["Diao Chan","Ma Chao","Liu Bei","Zhao Yun"]],["An arm can be scraped, but how can a head be split open? You must be Guan Yu's friend, using this chance to take revenge!","臂痛可刮，腦袋安可砍開？汝必與關公情熟，乘此機會欲報仇耳！","Cao Cao","曹操","Wei",78,"Rejecting Hua Tuo's offer of brain surgery",["Xu You","Zhao Yun","Yang Xiu","Cao Cao"]],["I'm young and know nothing. Prime Minister Father, you decide.","朕年幼無知，惟相父斟酌行之。","Liu Shan","劉禪","Shu",87,"Sending Zhuge Liang off to the south",["Huang Zhong","Xu Shu","Liu Shan","Zhao Yun"]]],[["I still have a mouth to swallow the traitor and a tongue to curse him!","尚有口可以吞賊，有舌可以罵賊！","Ji Ping","吉平","Han court and others",23,"After his tongue is threatened under torture",["Dong Zhuo","Wang Yun","Ji Ping","Sima Yi"]],["Everyone's scared of Zhang Fei. To me he's a child. I'll capture him this time!","人皆怕張飛，吾視之如小兒耳。此去必擒之！","Zhang He","張郃","Wei",69,"Marching against Zhang Fei at Dangqu",["Zhang He","Huang Zhong","Jiang Gan","Zhang Liao"]],["Now I understand what happened with Shun and Yu!","舜、禹之事，朕知之矣！","Cao Pi","曹丕","Wei",80,"After the Han emperor abdicates to him",["Xu Huang","Deng Ai","Xiahou Dun","Cao Pi"]]],[["Hearing you're leaving is like losing my left and right hands. Even dragon liver and phoenix marrow would taste of nothing.","備聞公將去，如失左右手，雖龍肝鳳髓，亦不甘味。","Liu Bei","劉備","Shu",36,"At the farewell banquet for Xu Shu",["Sun Quan","Liu Bei","Ma Chao","Cao Cao"]],["Liu Bei is a fish in a pot, a tiger in a pit. Fail to catch him now and we release the fish to the sea and the tiger to the mountains.","今劉備釜中之魚，阱中之虎；若不就此時擒捉，如放魚入海，縱虎歸山矣。眾將可努力向前。","Cao Cao","曹操","Wei",42,"Pressing the chase after Changban",["Sima Yi","Cao Cao","Yang Xiu","Pang De"]],["You dare look down on me? I'll hold the other fifty strokes. Slack again and you'll get both punishments!","汝敢小覷我耶！且寄下五十棍。再有怠慢，二罪俱罰！","Zhou Yu","周瑜","Wu",46,"Halting Huang Gai's beating halfway",["Lady Wu","Zhou Yu","Kan Ze","Huang Gai"]]],[["If I've really found the treasure and hidden it, may I die a bad death, under swords and arrows!","吾若果得此寶私自藏匿，異日不得善終，死刀箭之下！","Sun Jian","孫堅","Wu",6,"Swearing he doesn't have the imperial seal",["Sun Ce","Sun Jian","Yuan Shao","Chen Gong"]],["How narrow minded he is! I have a plan to beat Cao. He didn't ask me, so I didn't tell him.","何如此不能容物耶！我自有破曹之計，彼不問我，我故不言。","Zhuge Liang","諸葛亮","Shu",43,"After storming out of Sun Quan's audience",["Xu Shu","Zhuge Liang","Lu Su","Guan Yu"]],["People say Mengde is a treacherous hero. Now I see it's true.","世人皆言孟德奸雄，今果然也。","Xu You","許攸","Wei",30,"Laughing at Cao Cao's lies about his supplies",["Xu You","Zhang Liao","Xiahou Dun","Wang Lang"]]],[["I've been leading armies all my life. Am I to be outdone by a yellow mouthed boy?","朕用兵老矣，豈反不如一黃口孺子耶？","Liu Bei","劉備","Shu",83,"Scorning Lu Xun before Yiling",["Liu Bei","Ma Chao","Huang Zhong","Guan Yu"]],["If Heaven's mandate lies with me, I shall be King Wen of Zhou.","吾事漢多年，雖有功德及民，然位至於王，名爵已極，何敢更有他望？苟天命在孤，孤爲周文王矣。","Cao Cao","曹操","Wei",78,"Declining to make himself emperor while leaving the door open for his son",["Cao Ren","Sun Quan","Cao Cao","Zhang Liao"]],["If you're this afraid of the old traitor, I'll never see the light of day!","君如此懼怕老賊，妾身無見天日之期矣！","Diao Chan","貂蟬","Han court and others",8,"Pushing Lü Bu to act",["Diao Chan","He Jin","Mi Heng","Dong Zhuo"]]],[["Kongming eats little and works hard. How long can he last?","孔明食少事煩，其能久乎？","Sima Yi","司馬懿","Wei",103,"After quizzing Zhuge Liang's envoy about his master's routine",["Wang Yun","Liu Bei","Zhang Liao","Sima Yi"]],["Zhongmou is shortsighted, making this boy a general!","仲謀見識短淺，用此孺子爲將！","Guan Yu","關羽","Shu",75,"Hearing Lu Xun has replaced Lü Meng",["Sima Yi","Guan Yu","Wei Yan","Ma Dai"]],["I've won battle after battle and Xiangyang will fall any day. How can I quit just because the wind snapped a flagpole?","吾屢戰屢勝，取襄陽只在旦夕。豈可因風折旗竿，遽爾罷兵！","Sun Jian","孫堅","Wu",7,"Ignoring a bad omen shortly before his death",["Sun Jian","Zhang Zhao","Lü Meng","Lady Wu"]]],[["Will you really not teach me? Then my life is lost. Let me die right here in front of you, sir!","先生終不幸教琦乎！琦命固不保矣，請即死於先生之前。","Liu Qi","劉琦","Rival warlords",39,"Trapping Zhuge Liang upstairs after taking away the ladder",["Guan Yu","Liu Qi","Sun Ce","Meng Huo"]],["For strategy we rely on Kongming, for courage on you two. Why are you dragging your feet?","智賴孔明，勇須二弟，何可推調？","Liu Bei","劉備","Shu",39,"Before the battle at Bowang",["Chen Gong","Ma Dai","Liu Bei","Pang Tong"]],["This isn't the Hongmen Feast. What need is there for a Xiang Zhuang or a Xiang Bo?","此非鴻門會，安用項莊、項伯乎？","Cao Cao","曹操","Wei",21,"Laughing when Guan Yu and Zhang Fei burst in with swords drawn at the plum wine meeting",["Cheng Yu","Cao Cao","Xu You","Deng Ai"]]],[["The Young Phoenix is Pang Tong of Xiangyang. The Sleeping Dragon is Zhuge Kongming.","鳳雛乃襄陽龐統也。伏龍正是諸葛孔明。","Xu Shu","徐庶","Shu",36,"Finally naming the two great talents to Liu Bei",["Yuan Shao","Huang Zhong","Dong Zhuo","Xu Shu"]],["I've been raised and trained by you with such kindness that even if I were ground to powder I couldn't repay a ten thousandth of it. If I can be of use, I won't refuse even ten thousand deaths!","妾蒙大人恩養，訓習歌舞，優禮相待，妾雖粉身碎骨，莫報萬一。……倘有用妾之處，萬死不辭！","Diao Chan","貂蟬","Han court and others",8,"Overheard sighing in the garden at night",["Zuo Ci","Hua Tuo","Guan Yu","Diao Chan"]],["This is the old general's trick of making the enemy cocky.","此乃老將驕兵之計也。","Zhuge Liang","諸葛亮","Shu",70,"Explaining Huang Zhong's string of fake retreats",["Zhuge Liang","Xu Shu","Fa Zheng","Jiang Wan"]]],[["Yunchang is dead. Now I can sleep soundly at last.","雲長已死，吾夜眠貼席矣。","Cao Cao","曹操","Wei",77,"On hearing of Guan Yu's death",["Wang Yun","Cao Cao","Yang Xiu","Liu Bei"]],["Gaining it is nothing to celebrate, losing it is nothing to mourn.","得何足喜，失何足憂！","Liu Bei","劉備","Shu",14,"Shrugging off the loss of Xuzhou",["Meng Huo","Ma Dai","Ma Chao","Liu Bei"]],["I owe you so much, Chancellor, that even dying I couldn't repay a ten thousandth of it.","某感丞相大恩，雖死不能報萬一。","Guo Jia","郭嘉","Wei",33,"Falling ill on the northern campaign",["Guo Jia","Xu You","Cao Cao","Cao Ren"]]],[["If you're still not convinced, I'll release you. How about that?","汝既不服，吾放汝去，若何？","Zhuge Liang","諸葛亮","Shu",87,"After capturing Meng Huo for the first time",["Ma Chao","Chen Gong","Zhuge Liang","Yang Xiu"]],["After Zhou Lang came Lu Su, after Lu Su came Lü Meng. Now Lü Meng is gone, there's no one to share my worries.","周郎之後有魯肅，魯肅之後有呂蒙，今呂蒙已亡，無人與孤分憂也。","Sun Quan","孫權","Wu",82,"As Liu Bei's army marches on Wu",["Huang Zhong","Lu Xun","Sun Ce","Sun Quan"]],["Those above are swollen with pride, those below chase rewards. Oh endless Yellow River, can we really cross you?","上盈其志，下務其功；悠悠黃河，吾其濟乎！","Ju Shou","沮授","Rival warlords",26,"Sighing as Yuan Shao's army heads south",["Liu Qi","Ju Shou","Liu Zhang","Yuan Shao"]]],[["Anyone who undertakes great deeds must take the people as the root. The people follow me now. How can I abandon them?","舉大事者必以人爲本。今人歸我，奈何棄之？","Liu Bei","劉備","Shu",41,"Refusing to leave the refugees behind",["Cao Cao","Zhuge Liang","Yang Xiu","Liu Bei"]],["I have dozens of men under me, all heroes of the age. How can you say there's nobody?","吾手下有數十人，皆當世英雄，何謂無人？","Cao Cao","曹操","Wei",23,"Stung by Mi Heng's insults",["Liu Bei","Zhang Liao","Cao Cao","Xiahou Dun"]],["I bit it off as a vow to kill the traitor!","嚼以爲誓，誓殺國賊！","Ji Ping","吉平","Han court and others",23,"Explaining his missing finger under torture",["Ji Ping","Zuo Ci","Sima Hui","Mi Heng"]]],[["The essence of my father and the blood of my mother! I cannot throw it away!","父精母血，不可棄也！","Xiahou Dun","夏侯惇","Wei",18,"Before swallowing his own eye after pulling out an arrow",["Zhang Liao","Xiahou Dun","Lu Su","Sun Ce"]],["I know. But the late emperor entrusted his son to me, and I fear no one else would serve as faithfully.","吾非不知。但受先帝託孤之重，惟恐他人不似我盡心也。","Zhuge Liang","諸葛亮","Shu",103,"Told he is working himself to death",["Ma Su","Guan Yu","Zhuge Liang","Zhao Yun"]],["Since taking command I haven't touched a drop. But today I see an old friend and have nothing to hide, so I'll get drunk.","吾自領軍以來，滴酒不飲；今日見了故人，又無疑忌，當飲一醉。","Zhou Yu","周瑜","Wu",45,"The banquet known as the Gathering of Heroes",["Zhou Yu","Cheng Pu","Zhou Tai","Lu Su"]]],[["Are you saying we lords have no great generals? A mere archer dares to talk like that? Throw him out!","汝欺吾眾諸侯無大將耶？量一弓手，安敢亂言！與我打出！","Yuan Shu","袁術","Rival warlords",5,"When Guan Yu volunteers to fight Hua Xiong",["Yuan Shu","Yuan Shao","Cao Cao","Sun Quan"]],["Haven't you heard of plans made in a tent deciding victory a thousand li away? Don't disobey orders, brothers.","豈不聞『運籌帷幄之中，決勝千里之外』？二弟不可違令。","Liu Bei","劉備","Shu",39,"Making Guan Yu and Zhang Fei obey Zhuge Liang",["Liu Bei","Guan Yu","Sun Quan","Ma Chao"]],["Chained ships are stable, but if they use fire we'll have no way to escape. We must prepare for that.","船皆連鎖，固是平穩；但彼若用火攻，難以迴避。不可不防。","Cheng Yu","程昱","Wei",48,"Worrying about Pang Tong's chain plan before Red Cliffs",["Cheng Yu","Xiahou Dun","Guo Jia","Jia Xu"]]],[["You want to see Lord Cao? I'm a man like you. I don't have four eyes or two mouths, just more brains.","汝諸軍欲觀曹公耶？吾亦猶人也，非有四目兩口，但多智謀耳。","Cao Cao","曹操","Wei",59,"Riding out in front of the curious Western Liang troops",["Lü Bu","Zhang Fei","Zhang Liao","Cao Cao"]],["An army isn't about numbers, it's about how it's used. This man is a real general!","兵不在多，在人之調遣耳。此人真將才也！","Zhuge Liang","諸葛亮","Shu",93,"After being outwitted at Tianshui",["Yang Xiu","Huang Zhong","Zhuge Liang","Ma Su"]],["My illness has made me deaf. Take care on your journey.","吾病的耳聾了。此去保重。","Sima Yi","司馬懿","Wei",106,"Fooling Cao Shuang's spy into thinking he is dying",["Sima Yi","Jiang Gan","Xu Huang","Deng Ai"]]],[["If I can't be your wife in this life, let's promise to meet in the next.","妾今生不能與君爲妻，願相期於來世。","Diao Chan","貂蟬","Han court and others",8,"Weeping to Lü Bu at the Phoenix Pavilion",["Diao Chan","Xu You","Sun Ce","Dong Zhuo"]],["Why does Heaven torment me like this? Things have come to such a pass, I may as well die!","天何使我受此窘極耶！事勢至此，不如就死！","Liu Bei","劉備","Shu",31,"At his lowest point after defeat at Runan",["Wei Yan","Lü Bu","Liu Bei","Zhuge Liang"]],["Loyal advice is ignored. We'll all pay for this!","忠言不入，吾輩必受殃矣！","Chen Gong","陳宮","Han court and others",18,"Walking out of Lü Bu's hall",["Chen Gong","Mi Heng","Hua Tuo","Sima Hui"]]],[["We all go off to fight while you sit at home taking it easy!","我們都去廝殺，你卻在家裏坐地，好自在！","Zhang Fei","張飛","Shu",39,"Grumbling at Zhuge Liang before Bowang",["Zhao Yun","Zhang Liao","Zhang Fei","Guan Yu"]],["Since I left my thatched cottage I've never lost a battle or failed to take a city. You men of the south, why won't you submit?","吾自出茅廬，戰無不勝，攻無不取。汝蠻邦之人，何爲不服？","Zhuge Liang","諸葛亮","Shu",88,"Lecturing Meng Huo during the southern campaign",["Pang Tong","Sun Quan","Zhuge Liang","Ma Chao"]],["I'm a rat or sparrow, but at least I'm human. You lot are just worms.","吾乃鼠雀，尚有人性，汝等只可謂之蜾蟲。","Mi Heng","禰衡","Han court and others",23,"Insulting Xun Yu and the officials seeing him off",["Chen Gong","Mi Heng","Hua Xiong","Kong Rong"]]],[["That village yokel Zhuge, how dare he!","諸葛村夫，安敢如此！","Cao Cao","曹操","Wei",41,"After his vanguard is burned out at Xinye",["Cao Cao","Zhang Liao","Yang Xiu","Meng Huo"]],["I'd rather die than do something so ungrateful.","吾寧死不忍作負義之事。","Liu Bei","劉備","Shu",40,"Refusing to seize Jing Province from his host Liu Biao",["Ma Dai","Liu Bei","Cao Cao","Ma Su"]],["We fought through ten thousand deaths and bled to take this city. How dare you boast!","吾等千生萬死，身冒血戰，奪得城池，汝安敢誇口？","Xu Chu","許褚","Wei",33,"Before killing Xu You, who keeps taking credit",["Deng Ai","Wang Lang","Cao Ren","Xu Chu"]]],[["Unless the young master stays, I won't let you go even if I die ten thousand deaths!","若不留下小主人，縱然萬死，亦不敢放夫人去！","Zhao Yun","趙雲","Shu",61,"Blocking Lady Sun's boat on the river",["Lu Su","Zhao Yun","Huang Zhong","Lü Bu"]],["You say I'm old? Dare you compete with me in arms?","汝說吾老，敢與我比試武藝麼？","Huang Zhong","黃忠","Shu",62,"Quarrelling with Wei Yan over who leads the attack",["Sun Ce","Guan Yu","Huang Zhong","Pang Tong"]],["Your son is off to receive the Han throne, mother. You'll soon be Empress Dowager.","兒將往受漢禪，母親早晚爲太后也。","Dong Zhuo","董卓","Han court and others",9,"Leaving for the capital and his death",["Dong Zhuo","Lü Bu","Ji Ping","Xu Shao"]]],[["You ring eyed thief! You keep looking down on me!","環眼賊！你累次渺視我！","Lü Bu","呂布","Han court and others",16,"Shouting at Zhang Fei over stolen horses",["Lü Bu","Dong Zhuo","Cao Cao","Yang Xiu"]],["I've been a bird in a cage, a fish in a net. This trip is like a fish entering the sea, a bird soaring to the blue sky.","吾乃籠中鳥、網中魚，此一行如魚入大海、鳥上青霄，不受籠網之羈絆。","Liu Bei","劉備","Shu",21,"Riding away from the capital with an army Cao Cao lent him",["Liu Bei","Ma Chao","Liu Shan","Yang Xiu"]],["I want the realm to trust my word. How could I go back on it? You might run short on the road, so I've brought money for the journey.","吾欲取信於天下，安肯有負前言。恐將軍途中乏用，特具路資相送。","Cao Cao","曹操","Wei",27,"Catching up with Guan Yu at the bridge to see him off",["Pang De","Cao Cao","Xun Yu","Wang Lang"]]],[["You people eating crook! Do you know who I am?","害民賊！認得我么？","Zhang Fei","張飛","Shu",2,"Dragging the corrupt inspector Du You out to be beaten",["Zhao Yun","Zhang Fei","Ma Chao","Huang Zhong"]],["After I die, Jiang Gongyan is the man for great affairs.","吾死之後，可任大事者：蔣公琰其宜也。","Zhuge Liang","諸葛亮","Shu",104,"Naming his successor on his deathbed",["Guan Yu","Zhuge Liang","Sima Yi","Liu Shan"]],["If you don't use Lu Boyan, Wu is finished! I'll stake my whole family on him!","若不用陸伯言，則東吳休矣！臣願以全家保之！","Kan Ze","闞澤","Wu",83,"Recommending Lu Xun to Sun Quan",["Kan Ze","Lady Wu","Zhou Yu","Sun Quan"]]],[["I'm not laughing at anything else. I'm laughing that none of you has a single plan to kill Dong Zhuo.","吾非笑別事，笑眾位無一計殺董卓耳。操雖不才，願即斷董卓頭，懸之都門，以謝天下。","Cao Cao","曹操","Wei",4,"At Wang Yun's banquet while the court officials weep",["Yuan Shao","Sima Yi","Cao Cao","Zhuge Liang"]],["Yunchang and I swore to live and die together. If anything happens to him, how could I go on alone?","孤與雲長，誓同生死。彼若有失，孤豈能獨生耶？","Liu Bei","劉備","Shu",77,"After a dream of Guan Yu's ghost",["Huang Zhong","Ma Su","Liu Bei","Sima Yi"]],["Who are you to fake a surrender? I need something to sacrifice to the flag, so I'll borrow your head.","汝是何等人，敢來詐降！吾今缺少福物祭旗，願借你首級。","Zhou Yu","周瑜","Wu",49,"Executing Cai Zhong before the fire attack",["Sun Quan","Sun Jian","Lady Sun","Zhou Yu"]]],[["Three surnamed slave, stop right there! Zhang Fei of Yan is here!","三姓家奴休走！燕人張飛在此！","Zhang Fei","張飛","Shu",5,"Charging Lü Bu at Hulao Pass",["Lu Su","Guan Yu","Zhang Fei","Zhuge Liang"]],["I want to kill Ding Yuan and take the army over to Dong Zhuo. What do you think?","吾欲殺丁原，引軍歸董卓，何如？","Lü Bu","呂布","Han court and others",3,"Won over by a gift of gold and a fine red horse",["Zhang Fei","Lü Bu","Sima Hui","Dong Zhuo"]],["With this boy as general, Wu is finished! Have you seen what he's doing?","今此孺子爲將，東吳休矣！公見彼所行乎？","Zhou Tai","周泰","Wu",83,"Grumbling about Lu Xun's refusal to fight at Yiling",["Zhang Zhao","Sun Jian","Zhou Tai","Cheng Pu"]]],[["Jade can be smashed, but its whiteness can't be changed. Bamboo can be burned, but its joints can't be destroyed.","玉可碎，而不可改其白，竹可焚，而不可毀其節。","Guan Yu","關羽","Shu",76,"Refusing to surrender while trapped at Maicheng",["Liu Bei","Xu You","Guan Yu","Sun Quan"]],["I've read military texts since I was a boy and I know every trick of deceit. This scheme might fool others, but not me!","吾自幼熟讀兵書，深知奸僞之道。汝這條計，只好瞞別人，如何瞞得我？","Cao Cao","曹操","Wei",47,"Interrogating Kan Ze over Huang Gai's surrender letter",["Zhuge Liang","Xu You","Deng Ai","Cao Cao"]],["Let's compete here in front of our lord. Whoever wins goes. How about it?","就主公之前，當面比試。贏得的便去，何如？","Wei Yan","魏延","Shu",62,"Arguing with Huang Zhong over who leads the attack",["Wei Yan","Ma Su","Fa Zheng","Ma Chao"]]],[["Man makes the plans, but Heaven decides the outcome. It can't be forced.","謀事在人，成事在天！不可強也。","Zhuge Liang","諸葛亮","Shu",103,"Watching rain put out the fire that should have killed Sima Yi",["Dong Zhuo","Huang Zhong","Sun Quan","Zhuge Liang"]],["The sage said impatience in small things ruins great plans. Holding firm is best.","聖人云：『小不忍則亂大謀。』但堅守爲上。","Sima Yi","司馬懿","Wei",103,"Refusing to be provoked out of his camp",["Wang Yun","Sima Yi","Xu You","Pang De"]],["Kong Wenju asked me to rescue Xuzhou out of righteousness. If I just take it for myself, the whole realm will call me a man without honour.","孔文舉令備來救徐州，爲義也。今無端據而有之，天下將以備爲無義人矣。","Liu Bei","劉備","Shu",11,"Refusing Tao Qian's offer of Xuzhou",["Lady Mi","Yan Yan","Guan Yu","Liu Bei"]]],[["I've never liked fighting. I only like stopping fights. I'll settle this for you both.","無有此理。布平生不好鬥，惟好解鬥。吾今爲兩家解之。","Lü Bu","呂布","Han court and others",16,"Arriving between Liu Bei and Ji Ling's armies",["Lu Su","Dong Zhuo","Lü Bu","Zhao Yun"]],["If their navy gets properly trained, my head will end up as a present for Zhou Lang!","軍若練熟，吾首級獻於周郎矣！","Cao Cao","曹操","Wei",45,"Reading a forged letter that frames his own admirals",["Cao Cao","Xu You","Yang Xiu","Zhang Liao"]],["I know you only took it to cover the official armour, but it still came from the people.","吾固知汝爲覆官鎧，然終是不應取民間之物。","Lü Meng","呂蒙","Wu",75,"Executing a soldier from his home town for taking a hat",["Lü Meng","Lu Su","Taishi Ci","Sun Quan"]]],[["From tonight's password I know the King will soon retreat. Chicken ribs: no meat to eat, yet a shame to throw away. Better pack now.","以今夜號令，便知魏王不日將退兵歸也：雞肋者，食之無肉，棄之有味。","Yang Xiu","楊修","Wei",72,"Explaining the password to the camp, which costs him his life",["Sun Ce","Yang Xiu","Dong Zhuo","Cao Cao"]],["I'm fifty, my hair is going white, and the Wu lord's sister is in the bloom of youth. Hardly a match.","吾年已半百，鬢髮斑白；吳侯之妹，正當妙齡：恐非配偶。","Liu Bei","劉備","Shu",54,"Told Sun Quan is offering his sister in marriage",["Ma Chao","Liu Shan","Liu Bei","Pang Tong"]],["I received great kindness from the late emperor and swore to repay it with my life. If traitors work against me at court, how can I fight the enemy?","老臣受先帝厚恩，誓以死報。今若內有奸邪，臣何能討賊乎？","Zhuge Liang","諸葛亮","Shu",101,"Recalled from the front by a suspicious emperor",["Zhuge Liang","Liu Bei","Jiang Wan","Jiang Wei"]]],[["For matters at home, ask Zhang Zhao. For matters abroad, ask Zhou Yu.","弟才勝兒十倍，足當大任。倘內事不決，可問張昭；外事不決，可問周瑜。恨周瑜不在此，不得面囑之也！","Sun Ce","孫策","Wu",29,"His last instructions to his brother",["Lu Su","Chen Gong","Sun Ce","Zhang Liao"]],["So many loyal men in Hebei! What a pity the Yuans couldn't use them. If they had, I'd never dare look this land in the eye!","河北義士，何其如此之多也！可惜袁氏不能用；若能用，則吾安敢正眼覷此地哉！","Cao Cao","曹操","Wei",33,"After yet another Yuan follower refuses to submit",["Zhou Yu","Xu Huang","Cao Cao","Deng Ai"]],["He's the one who once persuaded me to kill Ding Jianyang too. If he won't go, I'll cut him down first!","昔日勸吾殺丁建陽，亦此人也。今若不去，吾先斬之！","Lü Bu","呂布","Han court and others",9,"Sending Li Su to lure Dong Zhuo into the trap",["Mi Heng","Lü Bu","Sima Hui","Ji Ping"]]],[["No. I've watched him. His words outrun his abilities. He must not be given great responsibility. Watch him closely, Chancellor.","不然。朕觀此人，言過其實，不可大用。丞相宜深察之。","Liu Bei","劉備","Shu",85,"A deathbed warning about Ma Su",["Yang Xiu","Liu Bei","Zhao Yun","Pang Tong"]],["If I had a son like young Master Sun, I could die without regret!","使術有子如孫郎，死復何恨！","Yuan Shu","袁術","Rival warlords",15,"Admiring Sun Ce",["Zhuge Liang","Yuan Shu","Zhang Song","Meng Huo"]],["If you're going to kill me, kill me. Why ask so many questions?","殺便殺，何必多問！","Kan Ze","闞澤","Wu",47,"Refusing to plead with Cao Cao",["Sun Quan","Kan Ze","Lu Su","Huang Gai"]]],[["In war, attacking the heart is best and attacking cities is worst. Fighting the mind is best, fighting with soldiers is worst.","夫用兵之道：攻心爲上，攻城爲下；心戰爲上，兵戰爲下。","Ma Su","馬謖","Shu",87,"Advice to Zhuge Liang before the southern campaign",["Ma Su","Wang Yun","Zhuge Liang","Pang Tong"]],["How dare this pedant expose my failings!","豎儒怎敢揭吾短處！","Cao Cao","曹操","Wei",60,"After Zhang Song lists all his defeats",["Chen Gong","Guo Jia","Xun Yu","Cao Cao"]],["I'm just an idle man from the hills, no use to the world. Someone ten times better than me will come to help you. Go and find him.","山野閒散之人，不堪世用。自有勝吾十倍者來助公，公宜訪之。","Sima Hui","司馬徽","Han court and others",35,"Turning down Liu Bei's invitation",["Sima Hui","Mi Heng","Ji Ping","Xu Shao"]]],[["Brother, what are you doing? Have you forgotten our oath in the peach garden?","賢弟何故如此？豈忘了桃園結義耶？","Guan Yu","關羽","Shu",28,"When Zhang Fei attacks him at Gucheng",["Pang Tong","Diao Chan","Liu Bei","Guan Yu"]],["Brother said I was hot tempered. How about today?","哥哥道我躁暴，今日如何？","Zhang Fei","張飛","Shu",22,"After capturing Liu Dai with a clever trick instead of brute force",["Sima Yi","Zhang Fei","Ma Dai","Wei Yan"]],["If you don't want people to know, don't do it! The whole city knows and you're hiding it from me!","若要不知，除非莫爲。滿城百姓，那一個不知？你倒瞞我！","Lady Wu","吳國太","Wu",54,"Confronting her son about the marriage plot",["Lady Wu","Zhou Tai","Zhou Yu","Zhuge Jin"]]],[["Fengxiao is dead. Heaven is destroying me!","奉孝死，乃天喪吾也！","Cao Cao","曹操","Wei",33,"On the death of his favourite adviser",["Cao Cao","Sun Quan","Zhuge Liang","Sima Yi"]],["Mengde is too suspicious. He's killed good people by mistake!","孟德心多，誤殺好人矣！","Chen Gong","陳宮","Han court and others",4,"Discovering the pig being prepared for them",["Sun Quan","Dong Zhuo","Wang Yun","Chen Gong"]],["A warrior going into battle is either killed or wounded. That's natural. Why let a dream worry you?","壯士臨陣，不死帶傷，理之自然也。何故以夢寐之事疑心乎？","Pang Tong","龐統","Shu",63,"Brushing off Liu Bei's bad dream before Luo",["Ma Su","Fa Zheng","Yan Yan","Pang Tong"]]],[["Deceiving the emperor is what's rude. I'm showing the body my parents gave me to prove I'm clean!","欺君罔上，乃謂無禮。吾露父母之形，以顯清白之體耳！","Mi Heng","禰衡","Han court and others",23,"After stripping naked as Cao Cao's drummer",["Yang Xiu","Zhou Yu","Lü Bu","Mi Heng"]],["Now I understand the saying about Sleeping Dragon and Young Phoenix. Who'd have thought the great man was right in front of me. I had eyes but was blind!","今日方知伏龍、鳳雛之語，何期大賢只在目前。非先生言，備有眼如盲也！","Liu Bei","劉備","Shu",36,"After Xu Shu finally names Zhuge Liang",["Sun Ce","Wei Yan","Liu Bei","Huang Zhong"]],["Enemy general, don't run! I'm avenging Lord Guan!","賊將休走！吾今爲關公報仇！","Huang Zhong","黃忠","Shu",83,"In his last battle at Yiling",["Xu Shu","Huang Zhong","Liu Shan","Liu Chen"]]],[["I gave my word long ago. How can I break it? Each man serves his own master. Don't chase him.","吾昔已許之，豈可失信！彼各爲其主，勿追也。","Cao Cao","曹操","Wei",27,"Stopping his officers from pursuing Guan Yu",["Huang Zhong","Xu You","Cao Cao","Zhang Liao"]],["You want to fight general against general, army against army, or formation against formation?","汝欲鬥將？鬥兵？鬥陣法？","Zhuge Liang","諸葛亮","Shu",100,"Challenging Sima Yi on the battlefield",["Zhang Fei","Zhuge Liang","Guan Yu","Pang Tong"]],["I showed off too much and fell into Jiang Wei's trap!","我一時自逞其能，中姜維之計矣！","Deng Ai","鄧艾","Wei",113,"Caught by the formation at Changcheng",["Sima Yi","Xu Chu","Deng Ai","Zhang He"]]],[["You won't fight and you won't retreat. What's your game?","戰又不戰，退又不退，卻是何故？","Zhang Fei","張飛","Shu",42,"Roaring across Changban Bridge; one of Cao's officers falls dead from fright",["Pang Tong","Huang Zhong","Zhang Fei","Zhuge Liang"]],["If you die now, brother, you'll be guilty of three crimes.","兄今即死，其罪有三。","Zhang Liao","張遼","Wei",25,"Persuading Guan Yu to surrender at Tushan",["Deng Ai","Jia Xu","Liu Bei","Zhang Liao"]],["You're wrong, Director! I may be of the Han royal clan, but I'm still a subject. Doing this would be rebelling against the Han!","軍師之言差矣。劉備雖然漢之宗室，乃臣子也；若爲此事，是反漢矣！","Liu Bei","劉備","Shu",73,"Refusing to declare himself emperor",["Ma Dai","Liu Bei","Pang Tong","Liu Shan"]]],[["Your Highness must have heard that Lord Guan took a poisoned arrow in his right arm, and I scraped the bone with no flinching from him. This is a small illness. Why so suspicious?","大王曾聞關公中毒箭，傷其右臂，某刮骨療毒，關公略無懼色。今大王小可之疾，何多疑焉？","Hua Tuo","華佗","Han court and others",78,"Trying to persuade Cao Cao to accept brain surgery",["Xu You","Hua Tuo","Cao Cao","Diao Chan"]],["When you wrote that proclamation for Benchu, you could have listed my crimes. Why insult my father and grandfather?","汝前爲本初作檄，但罪狀孤可也，何乃辱及祖、父耶？","Cao Cao","曹操","Wei",32,"Confronting the writer Chen Lin after the fall of Ye",["Zhang Liao","Zhou Yu","Cao Cao","Sima Yi"]],["You think only you can lay out this formation? If I can lay it, don't you think I can change it?","汝道此陣只汝能布耶？吾既會佈陣，豈不知變陣！","Deng Ai","鄧艾","Wei",113,"Countering Jiang Wei's formation",["Sima Yi","Wang Lang","Xu Huang","Deng Ai"]]],[["You're just a nobody, what can you do? It's a shame to stain my Green Dragon blade on a rat like you!","量汝一匹夫，亦何能爲！可惜我青龍刀，斬汝鼠賊！","Guan Yu","關羽","Shu",74,"Answering Pang De's challenge",["Guan Yu","Liu Bei","Zhao Yun","Sun Ce"]],["Don't worry about the other roads into Shu. Only Yinping must be watched carefully. It's steep, but in time it will be lost.","蜀中諸道皆不必多憂；惟陰平之地切須仔細。此地雖險峻，久必有失。","Zhuge Liang","諸葛亮","Shu",104,"A dying warning about the route that later lets Wei invade",["Liu Bei","Zhang Fei","Zhuge Liang","Sima Yi"]],["He should be compared to Jiang Ziya, who made Zhou last eight hundred years, and Zhang Zifang, who made Han flourish for four hundred.","可比興周八百年之姜子牙、旺漢四百年之張子房也。","Sima Hui","司馬徽","Han court and others",37,"Describing Zhuge Liang's true worth",["Dong Zhuo","Lü Bu","Ji Ping","Sima Hui"]]],[["Dilu, Dilu! Today you'll be the end of me!","的盧，的盧！今日妨吾！","Liu Bei","劉備","Shu",34,"Trapped at the Tan Stream, just before the famous leap",["Chen Gong","Wang Yun","Liu Bei","Pang Tong"]],["Ziyi is a man of his word. He won't betray me.","子義乃信義之士，必不背我。","Sun Ce","孫策","Wu",15,"Letting Taishi Ci go to gather troops, trusting he'll be back by noon",["Sun Ce","Lady Wu","Sima Yi","Lu Su"]],["I treated you with sincerity and you wanted to kill me! If I don't kill you, you'll kill me!","吾以誠心待汝等，汝等反欲害我耶！吾不殺汝，汝必殺我！","Cao Cao","曹操","Wei",66,"Executing those who plotted with Empress Fu",["Cao Ren","Sima Yi","Cao Cao","Cao Mao"]]],[["Brother, why not send your 'water' out to fight?","哥哥何不使『水』去？","Zhang Fei","張飛","Shu",39,"Mocking Liu Bei's fish and water remark as Cao's army approaches",["Zhang Fei","Pang Tong","Sun Quan","Cao Cao"]],["We came up with the plans, lost the men and spent the money, and he just takes what's ready. Infuriating!","吾等用計策，損兵馬，費錢糧，他去圖現成，豈不可恨！","Zhou Yu","周瑜","Wu",52,"After Liu Bei's side seizes Nanjun",["Zhuge Jin","Lu Xun","Sun Ce","Zhou Yu"]],["It's my fault for not telling the wise from the foolish! Every army suffered losses, except Zilong, who didn't lose a single man or horse. How?","是吾不識賢愚，以致如此！各處兵將敗損，惟子龍不折一人一騎，何也？","Zhuge Liang","諸葛亮","Shu",96,"Greeting Zhao Yun after the failed first campaign",["Ma Chao","Huang Zhong","Guan Yu","Zhuge Liang"]]],[["Blue eyed boy, purple bearded rat! I swore with Imperial Uncle Liu in the peach garden to uphold the Han. How could I join a traitor like you?","碧眼小兒，紫髯鼠輩！吾與劉皇叔桃園結義，誓扶漢室，豈與汝叛漢之賊爲伍耶？我今誤中奸計，有死而已，何必多言！","Guan Yu","關羽","Shu",77,"Captured and brought before Sun Quan",["Guan Yu","Lü Bu","Meng Huo","Zhuge Liang"]],["My family has held noble titles for generations. How would I know some country bumpkin?","吾家屢世公侯，豈識村野匹夫！","Ma Chao","馬超","Shu",65,"Answering Zhang Fei's challenge at Jiameng Pass",["Guan Yu","Ma Chao","Yuan Shao","Ma Su"]],["Would you give your own wife to Lü Bu? Mention Diao Chan again and I'll cut your head off!","汝之妻肯與呂布否？貂蟬之事，再勿多言，言則必斬！","Dong Zhuo","董卓","Han court and others",9,"To Li Ru, who begs him to give Diao Chan away",["Hua Tuo","Dong Zhuo","Kong Rong","Ji Ping"]]],[["All is lost! This is my fault!","大事去矣！此吾之過也！","Zhuge Liang","諸葛亮","Shu",95,"Hearing that Jieting has fallen",["Zhao Yun","Ma Chao","Sun Ce","Zhuge Liang"]],["Such a rare chance, thrown away over a baby's illness! Our cause is finished! What a tragedy!","遭此難遇之時，乃以嬰兒之病失此機會，大事去矣！可痛惜哉！","Tian Feng","田豐","Rival warlords",24,"Striking the ground in despair at his lord's refusal",["Tian Feng","Yuan Shao","Ju Shou","Liu Bei"]],["I have a plan called Two Tigers Fighting over Food.","彧有一計，名曰『二虎競食』之計。","Xun Yu","荀彧","Wei",14,"Proposing a way to set Liu Bei and Lü Bu against each other",["Jia Xu","Xu Chu","Xun Yu","Zhang He"]]],[["I dare to kill you!","吾敢殺汝！","Ma Dai","馬岱","Shu",105,"The answer that comes from behind Wei Yan",["Zhuge Liang","Dong Zhuo","Zhao Yun","Ma Dai"]],["I don't want to kill all the way along the road, but I have no choice. When Lord Cao hears, he'll think I'm ungrateful.","吾非欲沿途殺人，奈事不得已也。曹公知之，必以我爲負恩之人矣。","Guan Yu","關羽","Shu",27,"After cutting his way through the passes",["Liu Bei","Zhang Fei","Ma Su","Guan Yu"]],["That boy Zhou Yu is doomed to die young. He'll never dare face my army again!","周瑜孺子，料必橫夭，再不敢正覷我兵！","Cao Ren","曹仁","Wei",51,"Thinking Zhou Yu is dying of his arrow wound",["Yang Xiu","Xu Huang","Pang De","Cao Ren"]]],[["Chicken ribs! Chicken ribs!","雞肋！雞肋！","Cao Cao","曹操","Wei",72,"Muttering the night password while stuck at Hanzhong",["Cao Cao","Yang Xiu","Yuan Shao","Xu You"]],["Cao Cao is suspicious by nature. He can command an army, but suspicion brings him defeat. I beat him with decoy troops.","操平生爲人多疑，雖能用兵，疑則多敗。吾以疑兵勝之。","Zhuge Liang","諸葛亮","Shu",72,"Explaining his victory at the Han River",["Ma Dai","Sima Yi","Ma Chao","Zhuge Liang"]],["Since I took the throne, treacherous heroes have risen one after another. First Dong Zhuo, then Li Jue and Guo Si. I suffered what no ordinary man suffers. Then came Cao Cao, whom I took for a pillar of the state, and he seized all power for himself.","朕自即位以來，奸雄并起。先受董卓之殃，後遭傕、汜之亂，常人未受之苦，吾與汝當之。後得曹操，以爲社稷之臣，不意專國弄權，擅作威福。","Emperor Xian","漢獻帝","Han court and others",20,"Weeping to Empress Fu after the hunt at Xutian",["Xu Shao","Emperor Xian","Diao Chan","Hua Tuo"]]],[["I'm a grown man with my own name. Why would I be your son?","吾堂堂丈夫，安肯爲汝子乎！","Lü Bu","呂布","Han court and others",3,"Turning on his adoptive father Ding Yuan",["Lü Bu","Diao Chan","Zhao Yun","Zhang Fei"]],["Once the fish is in the net, how long can it last?","魚入罾口，豈能久乎？","Guan Yu","關羽","Shu",74,"Watching Yu Jin camp in a low valley just before the flood",["Meng Huo","Guan Yu","Zhao Yun","Ma Chao"]],["The old traitor thinks Jiangdong has no men. How dare he insult us like this!","老賊以我江東無人，敢如此相侮耶！","Zhou Yu","周瑜","Wu",44,"Reading Cao Cao's letter",["Zhou Yu","Lady Sun","Huang Gai","Zhou Tai"]]],[["I'm weeping for Guo Fengxiao! If Fengxiao were here, I would never have suffered this disaster!","吾哭郭奉孝耳！若奉孝在，決不使吾有此大失也！","Cao Cao","曹操","Wei",50,"Safe in Nanjun after Red Cliffs",["Cao Cao","Yuan Shao","Yang Xiu","Ma Chao"]],["A man who doesn't plan far ahead will have troubles close at hand. Ziming sees a long way.","人無遠慮，必有近憂。子明之見甚遠。","Sun Quan","孫權","Wu",61,"Approving Lü Meng's plan to fortify Ruxu",["Sun Ce","Lu Su","Xu You","Sun Quan"]],["I know Qin Lang by sight. The man you killed isn't Qin Lang. How dare you deceive me!","吾向識秦朗；汝今斬者，并非秦朗。安敢欺我！","Zhuge Liang","諸葛亮","Shu",102,"Unmasking a false defector",["Jiang Wei","Xu Shu","Jiang Wan","Zhuge Liang"]]],[["If only I'd listened to the Chancellor, I wouldn't be ruined like this. How can I face my officials in Chengdu now?","朕早聽丞相之言，不致今日之敗。今有何面目復回成都見群臣乎！","Liu Bei","劉備","Shu",85,"After the disaster at Yiling",["Zhao Yun","Zhou Yu","Lu Su","Liu Bei"]],["Only Zhuge Liang could see through this plan of mine. By Heaven's luck he isn't here, so I can win a great victory!","吾這條計但瞞不過諸葛亮耳。天幸此人不在，使我成大功也。","Lu Xun","陸遜","Wu",84,"Before setting fire to Liu Bei's camps at Yiling",["Yuan Shao","Lü Meng","Lu Xun","Gan Ning"]],["One deadly threat removed from my side!","吾除卻一心腹之患也！","Dong Zhuo","董卓","Han court and others",8,"On hearing Sun Jian has been killed",["Wang Yun","Dong Zhuo","Sima Hui","Mi Heng"]]],[["If the Ma boy doesn't die, I'll have nowhere to be buried!","馬兒不死，吾無葬地矣！","Cao Cao","曹操","Wei",59,"After narrowly escaping Ma Chao",["Cao Cao","Pang Tong","Yang Xiu","Dong Zhuo"]],["I've read military texts since I was a boy. Can't I hold one Jieting?","某自幼熟讀兵書，頗知兵法，豈一街亭不能守耶？","Ma Su","馬謖","Shu",95,"Begging for the command at Jieting",["Wei Yan","Pang Tong","Cao Cao","Ma Su"]],["You want to wag your three inch tongue like Li Yiji persuading the King of Qi? Into the boiling cauldron with you!","汝不自料，欲掉三寸之舌，效酈生說齊乎？可速入油鼎。","Sun Quan","孫權","Wu",86,"Threatening Shu's envoy Deng Zhi",["Huang Gai","Zhou Tai","Sun Quan","Sun Jian"]]],[["My only regret is that the fire wasn't big enough to burn you to death, you traitor of the state!","可惜當日火不大，不曾燒死你這國賊！","Zhang Liao","張遼","Wei",19,"Cursing Cao Cao after being captured with Lü Bu",["Xu You","Zhou Yu","Zhang Liao","Zhuge Liang"]],["I'll go find him myself. If I run into him, one thrust and he's dead!","待我親自尋他去。若撞見時，一槍刺死！","Zhang Fei","張飛","Shu",41,"Believing Zhao Yun has defected at Changban",["Dong Zhuo","Xu Shu","Zhang Fei","Zhao Yun"]],["You said last time, \"Catch me once more and I'll submit.\" Well, how about now?","汝前者有言：『但再擒得，便肯降服！』今日如何？","Zhuge Liang","諸葛亮","Shu",88,"After capturing Meng Huo for the second time",["Zhuge Liang","Zhao Yun","Ma Dai","Liu Bei"]]],[["Ziyuan has come! My cause will succeed! Teach me how to beat Yuan Shao.","子遠肯來，吾事濟矣！願即教我以破紹之計。","Cao Cao","曹操","Wei",30,"Rushing out barefoot to greet a defector at Guandu",["Zhang Liao","Liu Bei","Cao Cao","Wang Yun"]],["I couldn't find the ladies or the young master, so I fell behind. How is that defecting?","我尋不見主母與小主人，因此落後，何言反耶？","Zhao Yun","趙雲","Shu",41,"Answering Zhang Fei's accusation at Changban",["Yang Xiu","Liu Shan","Huang Zhong","Zhao Yun"]],["Treating a great man so poorly, the fault is mine!","屈待大賢，吾之過也！","Liu Bei","劉備","Shu",57,"After discovering Pang Tong's genius",["Ma Su","Liu Bei","Huang Zhong","Lady Mi"]]],[["Big eared boy! Have you forgotten the day I shot the halberd at the camp gate?","大耳兒！不記轅門射戟時耶？","Lü Bu","呂布","Han court and others",19,"Cursing Liu Bei as he is led away",["Lü Bu","Zhao Yun","Sun Ce","Wang Yun"]],["No banquet is a good banquet, no gathering a good gathering. Better not to go.","筵無好筵，會無好會，不如不去。","Zhang Fei","張飛","Shu",34,"Warning Liu Bei against Liu Biao's feast",["Wei Yan","Zhang Fei","Sima Yi","Ma Su"]],["Kongming is talking nonsense. In the dead of winter, how can there be a southeast wind?","孔明之言謬矣。隆冬之時，怎得東南風乎？","Lu Su","魯肅","Wu",49,"Hearing Zhuge Liang promise a change in the wind",["Gan Ning","Zhuge Jin","Zhou Tai","Lu Su"]]],[["I would rather betray everyone under heaven than let anyone under heaven betray me.","寧教我負天下人，休教天下人負我。","Cao Cao","曹操","Wei",4,"On the run with Chen Gong, after killing Lü Boshe",["Sun Quan","Cao Cao","Sima Yi","Xu You"]],["Commander, don't say it yet. Let's each write it on our palm and see if we agree.","都督且休言，各自寫於手內，看同也不同。","Zhuge Liang","諸葛亮","Shu",46,"Comparing plans with Zhou Yu; both palms say fire",["Ma Dai","Liu Shan","Zhuge Liang","Lu Su"]],["So Kongming had a plan all along and provoked me on purpose. My shallow view nearly ruined everything.","原來孔明有良謀，故以言詞激我。我一時淺見，幾誤大事。","Sun Quan","孫權","Wu",43,"After Lu Su explains Zhuge Liang's rudeness",["Cheng Pu","Zhou Yu","Sun Quan","Taishi Ci"]]],[["Have you not seen what happened to Ding Jianyang and Dong Zhuo?","公不見丁建陽、董卓之事乎？","Liu Bei","劉備","Shu",19,"Reminding Cao Cao how Lü Bu treated his previous masters",["Ma Chao","Liu Bei","Guan Yu","Lü Bu"]],["My lord, don't hesitate. Surrender to Cao and the people of Wu will be safe, and our six commanderies preserved.","主公不必多疑。如降操，則東吳民安，江南六郡可保矣。","Zhang Zhao","張昭","Wu",43,"Leading the call to surrender before Red Cliffs",["Sima Yi","Huang Gai","Lady Wu","Zhang Zhao"]],["Your ancestors ate the salary of the Han. Instead of repaying the state, you laugh?","汝祖宗亦食祿漢朝，今不思報國，而反笑耶？","Wang Yun","王允","Han court and others",4,"Scolding Cao Cao at the birthday banquet",["Wang Yun","Kong Rong","He Jin","Hua Xiong"]]],[["He's my son in law! Who dares harm him?","我的女婿，誰敢害他！","Lady Wu","吳國太","Wu",54,"Furious to learn the marriage was a trap",["Sun Quan","Diao Chan","Wang Yun","Lady Wu"]],["You call yourself clean. Who then is filthy?","汝爲清白，誰爲污濁？","Cao Cao","曹操","Wei",23,"After Mi Heng strips naked in front of the court",["Lü Bu","Cao Cao","Xu Chu","Sima Yi"]],["Zijing, don't you know today's brutal beating of Huang Gongfu is part of a plan? Why would you ask me to intervene?","子敬豈不知公瑾今日毒打黃公覆，乃其計耶？如何要我勸他？","Zhuge Liang","諸葛亮","Shu",46,"Explaining the beating ruse to Lu Su",["Lady Mi","Yan Yan","Huang Zhong","Zhuge Liang"]]],[["How dare you trifle with my beloved concubine!","汝敢戲吾愛姬耶！","Dong Zhuo","董卓","Han court and others",8,"Catching Lü Bu with Diao Chan at the Phoenix Pavilion",["Chen Gong","Dong Zhuo","Wang Yun","Zhuge Liang"]],["Life and death are fated. How could a horse change that?","深感先生見愛。但凡人死生有命，豈馬所能妨哉！","Liu Bei","劉備","Shu",34,"Ignoring a warning that his horse Dilu brings bad luck",["Guan Yu","Liu Bei","Zhang Fei","Diao Chan"]],["They're many and we're few. We can't hold out long. Why not attack with fire?","彼眾我寡，不宜久持，何不用火攻之？","Huang Gai","黃蓋","Wu",46,"Proposing the plan that leads to Red Cliffs",["Zhou Tai","Gan Ning","Huang Gai","Lu Xun"]]],[["You don't know: the elder Qiao is the wife of the late General Sun Bofu, and the younger is my wife!","公有所不知，大喬是孫伯符將軍主婦，小喬乃瑜之妻也。","Zhou Yu","周瑜","Wu",44,"Furious at Zhuge Liang's suggestion",["Zhou Yu","Pang Tong","Lu Su","Sun Ce"]],["Gongfu is coming to surrender. Heaven is helping me!","公覆來降，此天助我也！","Cao Cao","曹操","Wei",49,"Watching Huang Gai's fire ships approach at Red Cliffs",["Zhao Yun","Yang Xiu","Jia Xu","Cao Cao"]],["For a subject to kill his master is a great wrong. I'll never do it.","以臣弒主，大不義也。吾決不爲。","Xu Huang","徐晃","Wei",14,"Refusing to murder Yang Feng before joining Cao Cao",["Pang De","Cao Cao","Cao Pi","Xu Huang"]]],[["You can cut off my head, but I swear I'll never surrender to Cao!","吾頭可斷，誓不降曹！","Huang Gai","黃蓋","Wu",44,"Slapping his forehead when Zhou Yu pretends Wu should give in",["Pang Tong","Huang Gai","Zhuge Liang","Sun Ce"]],["You show obedience on the outside but keep doubts inside. When things get urgent and you can't decide, disaster won't be far off!","將軍外託服從之名，內懷疑貳之見，事急而不斷，禍至無日矣！","Zhuge Liang","諸葛亮","Shu",43,"Goading Sun Quan into war with Cao Cao",["Xu Shu","Sun Ce","Zhuge Liang","Huang Zhong"]],["Getting you, General, is like parched sprouts getting sweet rain.","卓今得將軍，如旱苗之得甘雨也。","Dong Zhuo","董卓","Han court and others",3,"Welcoming Lü Bu after he kills Ding Yuan",["Zuo Ci","Dong Zhuo","Xu Shao","Kong Rong"]]],[["This child's life rests entirely on you, General!","此子性命全在將軍身上！","Lady Mi","糜夫人","Shu",41,"Handing Adou to Zhao Yun before throwing herself into a well",["Dong Zhuo","Guan Yu","Lady Mi","Huang Zhong"]],["You don't study, you only love horses and archery. That's the courage of a common fellow. What's so valuable about it?","汝不讀書，而好弓馬，此匹夫之勇，何足貴乎？","Cao Cao","曹操","Wei",72,"Scolding his son Cao Zhang",["Huang Zhong","Xun Yu","Xu Chu","Cao Cao"]],["When Chu executed Dechen, Duke Wen of Jin rejoiced. The realm isn't settled yet. Isn't it a waste to execute a man of strategy?","昔楚殺得臣而文公喜。今天下未定，而戮智謀之臣，豈不可惜乎？","Jiang Wan","蔣琬","Shu",96,"Pleading with Zhuge Liang to spare Ma Su",["Zhao Yun","Zhuge Liang","Jiang Wan","Lady Mi"]]],[["Ziyi, you've come all this way across rivers and lakes to be Cao Cao's persuader, haven't you?","子翼良苦：遠涉江湖，爲曹氏作說客耶？","Zhou Yu","周瑜","Wu",45,"Greeting his old classmate Jiang Gan",["Wang Yun","Yuan Shao","Zhou Yu","Sun Ce"]],["What insolence! Does he think I have no siege engines?","匹夫無禮太甚！豈欺吾無攻城之具耶？","Zhuge Liang","諸葛亮","Shu",97,"After a defiant reply from the defender of Chencang",["Ma Dai","Huang Zhong","Pang Tong","Zhuge Liang"]],["The late emperor once told me Sima Yi has the gaze of a hawk and the look of a wolf, and must never be given troops.","先時太祖武皇帝嘗謂臣曰：『司馬懿鷹視狼顧，不可付以兵權，久必爲國家大禍。』","Hua Xin","華歆","Wei",91,"Accusing Sima Yi of plotting rebellion",["Hua Xin","Xiahou Dun","Wang Lang","Jia Xu"]]],[["I strongly suspect someone else writes your poems for you. Walk seven steps and compose a poem. If you can, you live. If not, you will be severely punished.","吾深疑汝必用他人代筆。吾今限汝行七步吟詩一首。若果能，則免一死；若不能，則從重治罪。","Cao Pi","曹丕","Wei",79,"Testing his younger brother Cao Zhi",["Yang Xiu","Liu Bei","Cao Pi","Zhang Liao"]],["Now is the time to use heroes. Kill one man and lose the hearts of the whole realm?","方今正用英雄之時，不可殺一人而失天下之心。此郭奉孝與吾有同見也。","Cao Cao","曹操","Wei",16,"Refusing advice to get rid of Liu Bei early",["Guan Yu","Xun Yu","Xiahou Dun","Cao Cao"]],["What about the lives of the eight hundred and thirty thousand men here?","此間八十三萬人馬，性命如何？","Xu Shu","徐庶","Shu",48,"Catching Pang Tong as he leaves Cao's camp",["Guan Yu","Pang Tong","Jiang Wei","Xu Shu"]]],[["Kongming takes me for a woman?","孔明視我爲婦人耶？","Sima Yi","司馬懿","Wei",103,"Receiving a gift of women's clothing from Zhuge Liang",["Pang Tong","Zhang Liao","Chen Gong","Sima Yi"]],["Old as I am, I still have the courage of Lian Po and the vigour of Ma Yuan. Neither of them accepted being old. Why won't you use me?","我雖年邁，尚有廉頗之勇，馬援之雄。此二古人皆不服老，何故不用我耶？","Zhao Yun","趙雲","Shu",91,"Demanding a role in the first northern campaign",["Zhao Yun","Ma Chao","Ma Dai","Wang Yun"]],["Speed is everything in war. Striking a thousand li away with heavy baggage won't work. Use light troops and catch them unprepared.","兵貴神速。今千里襲人，輜重多而難以趨利，不如輕兵兼道以出，掩其不備。但須得識徑路者爲引導耳。","Guo Jia","郭嘉","Wei",33,"Advice during the campaign against the Wuhuan",["Jiang Gan","Jia Xu","Cao Ren","Guo Jia"]]],[["The ancients said: brothers are like hands and feet, wives and children are like clothing.","古人云：『兄弟如手足，妻子如衣服。』云：","Liu Bei","劉備","Shu",15,"Stopping Zhang Fei from killing himself after losing Xuzhou and the family",["Lu Su","Zhou Yu","Liu Bei","Zhao Yun"]],["Heaven itself has told you both to stop fighting!","此天令你兩家罷兵也！","Lü Bu","呂布","Han court and others",16,"After his arrow hits the small blade of his halberd",["Zhou Yu","Lü Bu","Chen Gong","Wang Yun"]],["Benchu had no strategy and wouldn't use your advice. Why are you still so stubborn? If I'd had you earlier, the realm would be no worry.","本初無謀，不用君言，君何尚執迷耶？吾若早得足下，天下不足慮也。","Cao Cao","曹操","Wei",30,"Trying to win over the captured Ju Shou",["Xun Yu","Cao Cao","Cao Ren","Guo Jia"]]],[["My lord, don't worry. With this blade and this bow, if a thousand come, a thousand die!","不須主公憂慮。憑某這口刀，這張弓，一千個來，一千個死！","Huang Zhong","黃忠","Shu",53,"Volunteering to face Guan Yu at Changsha",["Huang Zhong","Zhao Yun","Lü Bu","Xu You"]],["Everyone else here can surrender to Cao Cao. Only you, General, cannot.","恰纔眾人所言，深誤將軍。眾人皆可降曹操，惟將軍不可降曹操。","Lu Su","魯肅","Wu",43,"Taking Sun Quan aside during the surrender debate",["Lu Su","Sun Ce","Lady Sun","Cao Cao"]],["With Xingba I'm sure to beat Huang Zu!","吾得興霸，破黃祖必矣。","Sun Quan","孫權","Wu",38,"Welcoming a famous former river pirate",["Gan Ning","Sun Jian","Sun Quan","Taishi Ci"]]],[["Liu Bei is a dragon among men who has never found water. Now he has Jing Province, the trapped dragon is in the sea. How can I not be shaken?","劉備，人中之龍也，生平未嘗得水。今得荊州，是困龍入大海矣。孤安得不動心也！","Cao Cao","曹操","Wei",56,"Dropping his brush on hearing Liu Bei has Jing Province",["Cao Cao","Sima Yi","Zhang Fei","Sun Ce"]],["I've heard Guan Zhong and Yue Yi were great men whose deeds covered the world. Isn't Kongming overreaching by comparing himself to them?","某聞管仲、樂毅乃春秋、戰國名人，功蓋寰宇。孔明自比此二人，毋乃太過？","Guan Yu","關羽","Shu",37,"On the way to visit Zhuge Liang",["Guan Yu","Ma Chao","Sun Quan","Ma Dai"]],["I have a plan that will break Xiapi immediately, better than two hundred thousand troops.","某有一計，下邳城可立破，勝於二十萬師。","Guo Jia","郭嘉","Wei",19,"Proposing to flood Lü Bu's city",["Zhang Liao","Guo Jia","Xu Huang","Xu You"]]],[["Your heart was crooked, so I left you!","汝心術不正，吾故棄汝！","Chen Gong","陳宮","Han court and others",19,"Answering Cao Cao at White Gate Tower",["Chen Gong","Meng Huo","Pang Tong","Dong Zhuo"]],["I've received great kindness from the King of Wei. How could I bow my knee to anyone else?","吾受魏王厚恩，豈肯屈節於人！","Pang De","龐德","Wei",74,"Refusing to surrender after the flood at Fancheng",["Guo Jia","Xu Huang","Pang Tong","Pang De"]],["Add the character for living inside the gate and you get the word wide. The Chancellor thinks the garden gate is too wide.","門內添『活』字，乃闊字也。丞相嫌園門闊耳。","Yang Xiu","楊修","Wei",72,"Solving one of Cao Cao's riddles",["Xu Chu","Cao Mao","Yang Xiu","Cao Cao"]]],[["Who'd have thought the fate of the Han lies in your hands!","誰想漢天下卻在汝手中耶！隨我到畫閣中來。","Wang Yun","王允","Han court and others",8,"Discovering his singer's loyalty in the moonlit garden",["Pang Tong","Cao Cao","Diao Chan","Wang Yun"]],["I may have served the state, but this will surely shorten my life!","吾雖有功於社稷，必損壽矣！","Zhuge Liang","諸葛亮","Shu",90,"After burning the rattan armour army alive in a valley",["Zhuge Liang","Guan Yu","Huang Zhong","Xu You"]],["Once you saved my life. How could I not save yours now?","不然。昔日蒙兄救弟，今日弟安得不救兄？","Zhang Liao","張遼","Wei",25,"Walking up the hill alone to talk to Guan Yu",["Xu You","Jia Xu","Zhang Liao","Guo Jia"]]],[["Give me back my head!","還我頭來！","Guan Yu","關羽","Shu",77,"A voice crying out over Jade Spring Hill",["Sima Yi","Guan Yu","Huang Zhong","Cao Cao"]],["That's a child's view! I hold the power of the whole realm. What can the eunuchs do to me?","此小兒之見也。吾掌天下之權，十常侍敢待如何！","He Jin","何進","Han court and others",3,"Entering the palace, just before being ambushed",["Ji Ping","Diao Chan","He Jin","Hua Tuo"]],["I'm making plans for the whole realm. Why would I care about the common people?","吾爲天下計，豈惜小民哉！","Dong Zhuo","董卓","Han court and others",6,"Brushing off protests over burning Luoyang",["Hua Tuo","Dong Zhuo","He Jin","Emperor Xian"]]],[["Men suffer from never being content. Now I have Long, must I want Shu as well?","人苦不知足，既得隴復望蜀耶？","Cao Cao","曹操","Wei",67,"Turning down advice to march on Yi Province",["Chen Gong","Cao Cao","Guan Yu","Zhang Liao"]],["Three of the Five Tiger Generals are dead, and I still haven't avenged them. What a bitter grief!","五虎大將，已亡三人。朕尚不能復仇，深可痛哉！","Liu Bei","劉備","Shu",83,"After Huang Zhong dies at Yiling",["Zhang Fei","Liu Bei","Lü Bu","Wei Yan"]],["I march to punish traitors by imperial decree. How can you say I have no just cause?","吾奉詔討賊，何謂無名？","Zhuge Liang","諸葛亮","Shu",93,"Answering Wang Lang's challenge",["Zhuge Liang","Zhao Yun","Jiang Wan","Lady Mi"]]]];
